<template>
  <b-badge :variant="meta.variant" pill class="status-badge">{{ meta.text }}</b-badge>
</template>

<script>
export default {
  name: "StatusBadge",
  props: {
    status: { type: String, default: "" },
  },
  computed: {
    meta() {
      return this.$store.getters.statusMeta(this.status);
    },
  },
};
</script>

<style scoped>
.status-badge {
  font-weight: 500;
  padding: 0.4em 0.85em;
}
</style>
