      <small>เปิดให้ทำแบบประเมินตั้งแต่ {{ formatDate(settings.surveyOpenFrom) }}</small>
    </div>

    <div v-else-if="mySurvey" class="state-box state-box--success">
      <b-icon icon="check-circle-fill" font-scale="2"></b-icon>
      <h4 class="mt-2 mb-1">บันทึกแบบประเมินของท่าน เรียบร้อยแล้ว</h4>
      <div>
        คะแนนเฉลี่ยที่ท่านให้
        <strong>{{ mySurveyAverage }}</strong> / 5 · บันทึกเมื่อ {{ formatDateTime(mySurvey.createdAt) }}
