      </div>

      <!-- ตอนที่ 1 -->
      <b-card class="mb-3" header="ตอนที่ 1 ข้อมูลทั่วไปเกี่ยวกับผู้ให้ข้อมูล">
        <b-form-group label="1.1 เพศ" label-class="font-weight-bold" :state="state('sex')" :invalid-feedback="errors.sex">
          <b-form-radio-group v-model="form.sex" :options="options.sex" :state="state('sex')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group label="1.2 อายุ" label-class="font-weight-bold" :state="state('ageRange')" :invalid-feedback="errors.ageRange">
          <b-form-radio-group v-model="form.ageRange" :options="options.ageRange" :state="state('ageRange')" stacked></b-form-radio-group>
        </b-form-group>
      </b-card>

      <!-- ตอนที่ 2 -->
      <b-card class="mb-3" header="ตอนที่ 2 โรงพยาบาลที่เข้ารับการตรวจสุขภาพประจำปี">
        <b-form-group label="2. โรงพยาบาลที่เข้าตรวจ" label-class="font-weight-bold" class="mb-0">
          <b-form-input :value="participant.hospitalName" readonly></b-form-input>
          <small class="text-muted">ดึงจากโรงพยาบาลที่ท่านเลือกไว้ในระบบ</small>
        </b-form-group>
      </b-card>

      <!-- ตอนที่ 3 -->
      <b-card class="mb-3" header="ตอนที่ 3 ข้อมูลด้านสุขภาพและการเตรียมตัว">
        <b-form-group
          label="3.1 วันที่เข้ารับการตรวจสุขภาพท่านงดอาหารและเครื่องดื่มมาแล้วใช่หรือไม่ (อย่างน้อย 12 ชั่วโมงก่อนเจาะเลือด)"
          label-class="font-weight-bold"
          :state="state('fasting')"
          :invalid-feedback="errors.fasting"
        >
          <b-form-radio-group v-model="form.fasting" :options="options.yesNo" :state="state('fasting')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group
          label="3.2 ท่านนอนหลับพักผ่อนมาเพียงพอแล้วใช่หรือไม่ (อย่างน้อย 6 ชั่วโมง)"
          label-class="font-weight-bold"
          :state="state('sleep')"
          :invalid-feedback="errors.sleep"
        >
          <b-form-radio-group v-model="form.sleep" :options="options.yesNo" :state="state('sleep')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group
          label="3.3 ในระยะเวลา 1 ปีที่ผ่านมา ท่านมีปัญหาสุขภาพหรือการเจ็บป่วยหรือไม่"
          label-class="font-weight-bold"
          :state="state('hasHealthIssue')"
          :invalid-feedback="errors.hasHealthIssue"
        >
          <b-form-radio-group v-model="form.hasHealthIssue" :options="options.healthIssue" :state="state('hasHealthIssue')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group
          v-if="form.hasHealthIssue === 'มี'"
          :state="state('healthIssueDetail')"
          :invalid-feedback="errors.healthIssueDetail"
        >
          <b-form-input v-model="form.healthIssueDetail" placeholder="ระบุปัญหาสุขภาพ" :state="state('healthIssueDetail')" maxlength="200"></b-form-input>
        </b-form-group>
        <b-form-group label="3.4 ท่านสูบบุหรี่หรือไม่" label-class="font-weight-bold" :state="state('smoking')" :invalid-feedback="errors.smoking">
          <b-form-radio-group v-model="form.smoking" :options="options.smoking" :state="state('smoking')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group label="3.5 ท่านดื่มสุราหรือไม่" label-class="font-weight-bold" :state="state('drinking')" :invalid-feedback="errors.drinking">
          <b-form-radio-group v-model="form.drinking" :options="options.drinking" :state="state('drinking')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group label="3.6 การออกกำลังกาย" label-class="font-weight-bold" :state="state('exercise')" :invalid-feedback="errors.exercise" class="mb-0">
          <b-form-radio-group v-model="form.exercise" :options="options.exercise" :state="state('exercise')" stacked></b-form-radio-group>
        </b-form-group>
      </b-card>

      <!-- ตอนที่ 4 -->
      <b-card class="mb-3" header="ตอนที่ 4 ความพึงพอใจของท่านต่อการให้บริการของโรงพยาบาล">
        <div class="rating-legend mb-3">
          <div class="font-weight-bold text-danger mb-1">*หมายเหตุ ระดับคะแนนดาว</div>
          <div class="d-flex flex-wrap">
            <span v-for="n in 5" :key="n" class="mr-3 small">
              <b-icon v-for="s in n" :key="s" icon="star-fill" variant="warning" font-scale="0.9"></b-icon>
              = {{ n }} คะแนน
            </span>
          </div>
        </div>
        <b-form-group
          v-for="q in surveyQuestions"
          :key="q.id"
          :label="`${q.no} ${q.label}`"
          label-class="font-weight-bold"
          :state="state(q.id)"
          :invalid-feedback="errors[q.id]"
        >
          <b-form-rating v-model="form.ratings[q.id]" variant="warning" show-value :state="state(q.id)"></b-form-rating>
        </b-form-group>
      </b-card>

      <!-- ตอนที่ 5-7 -->
      <b-card class="mb-3" header="ตอนที่ 5-7 การพบแพทย์ การกลับมาตรวจ และผลตรวจ">
        <b-form-group label="5. ท่านรอพบแพทย์หรือไม่" label-class="font-weight-bold" :state="state('waitDoctor')" :invalid-feedback="errors.waitDoctor">
          <b-form-radio-group v-model="form.waitDoctor" :options="options.waitDoctor" :state="state('waitDoctor')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group label="6. ในปีต่อไปท่านจะกลับมาตรวจสุขภาพที่โรงพยาบาลนี้อีกหรือไม่" label-class="font-weight-bold" :state="state('returnNext')" :invalid-feedback="errors.returnNext">
          <b-form-radio-group v-model="form.returnNext" :options="options.returnNext" :state="state('returnNext')" stacked></b-form-radio-group>
        </b-form-group>
        <b-form-group label="7. ท่านพอใจกับผลตรวจสุขภาพของท่านหรือไม่" label-class="font-weight-bold" :state="state('resultSatisfied')" :invalid-feedback="errors.resultSatisfied" class="mb-0">
          <b-form-radio-group v-model="form.resultSatisfied" :options="options.resultSatisfied" :state="state('resultSatisfied')" stacked></b-form-radio-group>
        </b-form-group>
      </b-card>

      <!-- ตอนที่ 8 -->
      <b-card class="mb-3" header="ตอนที่ 8 ปัญหาหรือข้อเสนอแนะอื่น ๆ">
        <b-form-group :state="state('comment')" :invalid-feedback="errors.comment" class="mb-0">
          <b-form-textarea
            v-model="form.comment"
            placeholder="ระบุปัญหาหรือข้อเสนอแนะ (ไม่บังคับ)"
            rows="3"
            max-rows="6"
            :state="state('comment')"
          ></b-form-textarea>
          <small class="text-muted">{{ form.comment.length }}/500</small>
        </b-form-group>
      </b-card>

      <b-alert :show="submitted && errorCount > 0" variant="danger">
        <b-icon icon="exclamation-triangle-fill" class="mr-1"></b-icon>
        ยังกรอกไม่ครบหรือไม่ถูกต้อง {{ errorCount }} รายการ กรุณาตรวจสอบช่องที่มีกรอบสีแดง
      </b-alert>

      <b-button block variant="success" size="lg" type="submit" :disabled="submitting">
        <b-spinner v-if="submitting" small class="mr-2"></b-spinner>
        <b-icon v-else icon="send-fill" class="mr-1"></b-icon>
        {{ submitting ? "กำลังบันทึก..." : "ส่งแบบประเมินผล" }}
      </b-button>
    </b-form>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../mixins/common";

// สร้างฟอร์มเปล่า (ข้อมูลชั่วคราวของฟอร์ม ไม่ใช่ข้อมูลธุรกิจ)
const buildEmptyForm = (questions) => ({
  sex: null,
  ageRange: null,
  fasting: null,
  sleep: null,
  hasHealthIssue: null,
  healthIssueDetail: "",
  smoking: null,
  drinking: null,
  exercise: null,
  ratings: questions.reduce((acc, q) => {
    acc[q.id] = null;
    return acc;
  }, {}),
  waitDoctor: null,
  returnNext: null,
  resultSatisfied: null,
  comment: "",
});

export default {
  name: "SurveyForm",
  mixins: [common],
  data() {
    return {
      form: buildEmptyForm(this.$store.getters.surveyQuestions),
      submitted: false,
      submitting: false,
    };
  },
  computed: {
    ...mapGetters({
      participant: "myParticipant",
      mySurvey: "mySurvey",
      isSurveyOpen: "isSurveyOpen",
      settings: "settings",
      options: "surveyOptions",
      surveyQuestions: "surveyQuestions",
    }),
    errors() {
      return this.$store.getters.validateSurveyForm(this.form);
    },
    errorCount() {
      return Object.keys(this.errors).length;
    },
    requiredTotal() {
      // จำนวนข้อบังคับทั้งหมด = จำนวน error ของฟอร์มเปล่า
      const blank = buildEmptyForm(this.surveyQuestions);
      return Object.keys(this.$store.getters.validateSurveyForm(blank)).length;
    },
    progressPercent() {
      if (this.requiredTotal === 0) return 0;
      const done = Math.max(0, this.requiredTotal - this.errorCount);
      return Math.round((done / this.requiredTotal) * 100);
    },
    mySurveyAverage() {
      if (!this.mySurvey) return 0;
      const row = this.$store.getters
        .surveyRows(this.mySurvey.year)
        .find((s) => s.id === this.mySurvey.id);
      return row ? row.average : 0;
    },
  },
  methods: {
    // แสดงสถานะ valid/invalid เฉพาะหลังกดส่ง
    state(key) {
      if (!this.submitted) return null;
      return this.errors[key] ? false : null;
    },
    async submit() {
      this.submitted = true;
      if (this.errorCount > 0) {
        this.notify("แจ้งเตือน!", "กรุณากรอกแบบประเมินให้ครบถ้วน", "warning");
        this.$nextTick(() => {
          const el = this.$el.querySelector(".is-invalid, .text-danger.d-block, .invalid-feedback.d-block");
          if (el && el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "center" });
        });
        return;
      }
      if (this.submitting) return;
      this.submitting = true;
      try {
        await this.$store.dispatch("submitSurvey", this.form);
        this.notify("แจ้งเตือน!", `บันทึกแบบสำรวจปี ${this.$store.getters.yearBE} เรียบร้อย!`, "success");
        this.form = buildEmptyForm(this.surveyQuestions);
        this.submitted = false;
      } catch (error) {
        this.notifyError(error, "บันทึกไม่สำเร็จ");
      } finally {
        this.submitting = false;
      }
    },
  },
};
</script>

