<template>
  <div class="container py-4 choose-page">
    <page-header
      icon="building"
      variant="danger"
      title="เลือกโรงพยาบาล"
      subtitle="เลือกจังหวัดและโรงพยาบาลที่ต้องการเข้ารับการตรวจสุขภาพประจำปี"
    />

    <b-alert :show="needHospital" variant="warning" dismissible fade>
      <b-icon icon="exclamation-triangle-fill" class="mr-1"></b-icon>
      กรุณาเลือกโรงพยาบาลก่อน จึงจะทำแบบประเมินความพึงพอใจได้
    </b-alert>

    <!-- ไม่พบข้อมูล / ไม่มีสิทธิ์ -->
    <b-card v-if="!participant">
      <empty-state
        icon="person-x"
        title="ไม่พบข้อมูลที่ต้องการ"
        description="ไม่พบข้อมูลสิทธิ์ตรวจสุขภาพของพนักงานรายนี้ในปีที่เลือก"
      >
        <b-button variant="primary" :to="{ name: 'Home' }">กลับหน้าแรก</b-button>
      </empty-state>
    </b-card>

    <template v-else>
      <div class="text-center mb-3">
        <div class="font-weight-bold text-primary h5 mb-0">
          {{ participant.employeeCode }} {{ participant.fullName }}
        </div>
        <small class="text-muted">พบปัญหา กรุณาติดต่อ Admin</small>
      </div>

      <b-alert :show="!!blockedReason" variant="danger">
        <b-icon icon="slash-circle-fill" class="mr-1"></b-icon>{{ blockedReason }}
      </b-alert>

      <!-- ฟอร์มเลือกโรงพยาบาล -->
      <b-card class="mb-4">
        <b-form novalidate @submit.prevent="save">
          <b-form-group label="ประจำปี" label-for="input-year" label-cols-sm="4" label-align-sm="right">
            <b-form-input id="input-year" :value="yearBE" disabled></b-form-input>
          </b-form-group>

          <b-form-group
            label="จังหวัด"
            label-for="select-province"
            label-cols-sm="4"
            label-align-sm="right"
            :state="provinceState"
            :invalid-feedback="provinceError"
          >
            <b-form-select
              id="select-province"
              v-model="form.province"
              :options="provinceOptions"
              :state="provinceState"
              :disabled="!canChange || saving"
              @change="onProvinceChange"
            >
              <template #first>
                <b-form-select-option :value="null" disabled>-- กรุณาเลือกจังหวัด --</b-form-select-option>
              </template>
            </b-form-select>
          </b-form-group>

          <b-form-group
            label="โรงพยาบาล"
            label-for="select-hospital"
            label-cols-sm="4"
            label-align-sm="right"
            :state="hospitalState"
            :invalid-feedback="hospitalError"
          >
            <b-form-select
              id="select-hospital"
              v-model="form.hospitalId"
              :options="hospitalOptions"
              :state="hospitalState"
              :disabled="!canChange || saving || !form.province"
            >
              <template #first>
                <b-form-select-option :value="null" disabled>-- เลือกโรงพยาบาล --</b-form-select-option>
              </template>
            </b-form-select>
            <small v-if="!form.province" class="text-muted">เลือกจังหวัดก่อน</small>
          </b-form-group>

          <b-button
            block
            type="submit"
            variant="success"
            size="lg"
            :disabled="!canChange || saving || !hasChanged"
          >
            <b-spinner v-if="saving" small class="mr-2"></b-spinner>
            <b-icon v-else icon="check2-circle" class="mr-1"></b-icon>
            {{ saving ? "กำลังบันทึก..." : "บันทึกโรงพยาบาล" }}
          </b-button>
          <small v-if="canChange && !hasChanged && participant.hospitalId" class="text-muted d-block text-center mt-2">
            ยังไม่มีการเปลี่ยนแปลงโรงพยาบาล
          </small>
        </b-form>
      </b-card>

      <!-- ข้อมูลของฉัน -->
      <b-card header="ข้อมูลการตรวจสุขภาพของคุณ">
        <b-table stacked small borderless :items="rows" :fields="fields">
          <template #cell(yearBE)>{{ participant.year + 543 }}</template>
          <template #cell(programName)="data">
            <div class="d-flex align-items-center">
              <span class="text-info font-weight-bold mr-2">{{ display(data.value) }}</span>
              <b-icon
                v-if="selectedProgram"
                v-b-popover.hover="'คลิกดูรายละเอียด'"
                icon="info-circle-fill"
                variant="info"
                scale="1.2"
                class="pointer"
                @click="openProgram"
              ></b-icon>
            </div>
          </template>
          <template #cell(hospitalName)="data">
            <span :class="data.value ? 'text-success font-weight-bold' : 'text-danger font-weight-bold'">
              {{ data.value || "ยังไม่เลือกโรงพยาบาล" }}
            </span>
          </template>
          <template #cell(checkupDate)="data">{{ formatDate(data.value) }}</template>
          <template #cell(status)="data"><status-badge :status="data.value" /></template>
        </b-table>
      </b-card>
    </template>

    <program-info-modal :program="selectedProgram" />
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import PageHeader from "../../components/PageHeader.vue";
import EmptyState from "../../components/EmptyState.vue";
import StatusBadge from "../../components/StatusBadge.vue";
import ProgramInfoModal from "../../components/ProgramInfoModal.vue";

export default {
  name: "ChooseHospital",
  components: { PageHeader, EmptyState, StatusBadge, ProgramInfoModal },
  mixins: [common],
  data() {
    return {
      // ข้อมูลฟอร์มชั่วคราว (ยังไม่บันทึกเข้า Store จนกว่าจะกด Save)
      form: { province: null, hospitalId: null },
      submitted: false,
      saving: false,
      fields: [
        { key: "employeeCode", label: "รหัส" },
        { key: "fullName", label: "ชื่อ-นามสกุล" },
        { key: "yearBE", label: "ประจำปี" },
        { key: "programName", label: "โปรแกรม" },
        { key: "hospitalName", label: "โรงพยาบาล" },
        { key: "checkupDate", label: "วันเข้าตรวจ" },
        { key: "status", label: "สถานะ" },
      ],
    };
  },
  computed: {
    ...mapGetters([
      "currentYear",
      "yearBE",
      "isAdmin",
      "myParticipant",
      "participantByCode",
      "provincesWithHospitals",
      "activeHospitals",
      "programById",
      "isHospitalSelectionOpen",
    ]),
    needHospital() {
      return this.$route.query.need === "hospital";
    },
    // Admin เปิดดูพนักงานรายอื่นได้ผ่าน /choose_hospital/:eid
    participant() {
      const eid = this.$route.params.eid;
      if (eid && this.isAdmin) return this.participantByCode(eid, this.currentYear);
      return this.myParticipant;
    },
    rows() {
      return this.participant ? [this.participant] : [];
    },
    selectedProgram() {
      if (!this.participant || !this.participant.programId) return null;
      const program = this.programById(this.participant.programId);
      return program && program.items.length > 0 ? program : null;
    },
    provinceOptions() {
      return this.provincesWithHospitals.map((p) => ({ value: p, text: p }));
    },
    hospitalOptions() {
      return this.activeHospitals
        .filter((h) => h.province === this.form.province)
        .map((h) => ({ value: h.id, text: h.nameTh }));
    },
    blockedReason() {
      const p = this.participant;
      if (!p) return "";
      if (p.status === "cancelled") return "คุณไม่มีสิทธิ์ตรวจสุขภาพ";
      if (this.isAdmin) return "";
      if (!this.isHospitalSelectionOpen) return "หมดเวลาเลือกโรงพยาบาล ติดต่อ HR";
      if (p.status === "completed") return "เข้ารับการตรวจแล้ว ไม่สามารถเปลี่ยนโรงพยาบาลได้";
      return "";
    },
    canChange() {
      return !!this.participant && !this.blockedReason;
    },
    hasChanged() {
      return !!this.participant && this.form.hospitalId !== this.participant.hospitalId;
    },
    provinceError() {
      return this.submitted && !this.form.province ? "กรุณาเลือกจังหวัด" : "";
    },
    hospitalError() {
      if (!this.submitted) return "";
      if (!this.form.hospitalId) return "กรุณาเลือกโรงพยาบาล";
      if (!this.hospitalOptions.some((o) => o.value === this.form.hospitalId)) {
        return "โรงพยาบาลที่เลือกไม่อยู่ในจังหวัดนี้";
      }
      return "";
    },
    provinceState() {
      return this.submitted ? !this.provinceError : null;
    },
    hospitalState() {
      return this.submitted ? !this.hospitalError : null;
    },
  },
  watch: {
    // เมื่อเปลี่ยนพนักงาน หรือข้อมูลถูกรีเซ็ต ให้โหลดค่าในฟอร์มใหม่
    participant: {
      immediate: true,
      handler(value, old) {
        if (!old || !value || value.id !== old.id || value.hospitalId !== old.hospitalId) {
          this.resetForm();
        }
      },
    },
  },
  methods: {
    resetForm() {
      const p = this.participant;
      const hospital = p && p.hospitalId ? this.$store.getters.hospitalById(p.hospitalId) : null;
      this.form = {
        province: hospital ? hospital.province : null,
        hospitalId: p ? p.hospitalId : null,
      };
      this.submitted = false;
    },
    onProvinceChange() {
      // ล้างโรงพยาบาลที่เลือกไว้ หากไม่อยู่ในจังหวัดใหม่
      if (!this.hospitalOptions.some((o) => o.value === this.form.hospitalId)) {
        this.form.hospitalId = null;
      }
    },
    openProgram() {
      this.$bvModal.show("bv-pro-info");
    },
    async save() {
      this.submitted = true;
      if (this.provinceError || this.hospitalError || this.saving) return;
      this.saving = true;
      try {
        const updated = await this.$store.dispatch("selectHospital", {
          participantId: this.participant.id,
          hospitalId: this.form.hospitalId,
        });
        this.notify(
          "แจ้งเตือน!",
          `บันทึกโรงพยาบาล "${updated.hospitalName}" ประจำปี ${this.yearBE} เรียบร้อย!`,
          "success"
        );
        if (this.needHospital) this.replaceRoute({ name: "choose_hospital" });
      } catch (error) {
        this.notifyError(error, "บันทึกไม่สำเร็จ");
      } finally {
        this.saving = false;
      }
    },
  },
};
</script>

<style scoped>
.choose-page {
  max-width: 760px;
}
</style>
