// src/utils/format.js
// ฟังก์ชันจัดรูปแบบสำหรับแสดงผล (ไม่มีข้อมูลธุรกิจ)
const THAI_MONTHS = ["ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.", "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."];
const pad2 = (n) => String(n).padStart(2, "0");

/** "2026-10-15" หรือ ISO datetime -> "15 ต.ค. 2569" (ไม่มีข้อมูลแสดง "-") */
export const formatDate = (value) => {
  if (!value) return "-";
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value));
  let year;
  let month;
  let day;
  if (dateOnly) {
    year = Number(dateOnly[1]);
    month = Number(dateOnly[2]) - 1;
    day = Number(dateOnly[3]);
  } else {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "-";
    year = date.getFullYear();
    month = date.getMonth();
    day = date.getDate();
  }
  if (month < 0 || month > 11) return "-";
  return `${day} ${THAI_MONTHS[month]} ${year + 543}`;
};

/** ISO datetime -> "15 ต.ค. 2569 09:30 น." */
export const formatDateTime = (value) => {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";
  return `${formatDate(value)} ${pad2(date.getHours())}:${pad2(date.getMinutes())} น.`;
};
