            <b-button variant="light" class="mr-2 mb-2" :to="{ name: 'choose_hospital' }">
              <b-icon icon="building" class="mr-1"></b-icon>
              {{ hasHospital ? "ดู / เปลี่ยนโรงพยาบาล" : "เลือกโรงพยาบาล" }}
            </b-button>
            <b-button variant="outline-light" class="mb-2" :to="{ name: 'summary' }">
              <b-icon icon="card-list" class="mr-1"></b-icon>ดูข้อมูลพนักงาน
            </b-button>
          </b-col>
          <b-col cols="12" lg="5" class="mt-3 mt-lg-0">
            <div class="hero-status">
              <div class="small text-uppercase hero-sub mb-2">สถานะของฉัน</div>
              <template v-if="myParticipant">
                <div class="d-flex align-items-center mb-2">
                  <status-badge :status="myParticipant.status" class="mr-2" />
                  <span class="font-weight-bold">{{ myParticipant.programName || "ยังไม่ระบุโปรแกรม" }}</span>
                </div>
                <div v-if="hasHospital">
                  <b-icon icon="building" class="mr-1"></b-icon>{{ myParticipant.hospitalName }}
                </div>
                <div v-else class="hero-warning">
                  <b-icon icon="exclamation-circle-fill" class="mr-1"></b-icon>ยังไม่ได้เลือกโรงพยาบาล
                </div>
                <div class="mt-1 small hero-sub">
                  วันที่เข้าตรวจ: {{ formatDate(myParticipant.checkupDate) }}
                </div>
              </template>
              <div v-else class="hero-warning">
                <b-icon icon="exclamation-circle-fill" class="mr-1"></b-icon>ไม่พบข้อมูลสิทธิ์ตรวจสุขภาพของคุณในปีนี้
              </div>
            </div>
          </b-col>
        </b-row>
      </b-card-body>
    </b-card>

    <!-- ตัวเลขภาพรวม -->
    <b-row class="mb-2">
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="โรงพยาบาลที่เปิดให้เลือก" :value="overview.hospitalCount" icon="building" variant="info" />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card
          label="ผู้เข้ารับการตรวจ"
          :value="overview.participantCount"
          icon="people-fill"
          variant="primary"
          :hint="`เลือกโรงพยาบาลแล้ว ${counts.selected}/${counts.eligible} คน`"
        />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="ตรวจเสร็จสิ้น" :value="counts.completed" icon="check2-circle" variant="success" />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card
          label="Checklist เสร็จแล้ว"
          :value="`${overview.checklistCompleted}/${overview.checklistTotal}`"
          icon="card-checklist"
          variant="warning"
          :hint="`ความคืบหน้า ${overview.checklistPercent}%`"
        />
      </b-col>
    </b-row>

    <!-- ความคืบหน้า -->
    <b-row class="mb-2">
      <b-col cols="12" lg="7" class="mb-3">
        <b-card class="h-100">
          <div class="d-flex justify-content-between align-items-baseline mb-3">
            <h5 class="font-weight-bold mb-0">ความคืบหน้าการตรวจสุขภาพ</h5>
            <span class="display-4 percent-text">{{ counts.percent }}<small>%</small></span>
          </div>
          <b-progress :max="counts.total || 1" height="1.4rem" class="mb-3">
            <b-progress-bar variant="success" :value="counts.completed" />
            <b-progress-bar variant="info" :value="counts.inProgress" />
            <b-progress-bar variant="secondary" :value="counts.pending" />
            <b-progress-bar variant="danger" :value="counts.cancelled" />
          </b-progress>
          <div class="d-flex flex-wrap">
            <div v-for="item in legend" :key="item.value" class="mr-4 mb-1">
              <b-badge :variant="item.variant" pill class="mr-1">&nbsp;</b-badge>
              {{ item.text }} <strong>{{ item.count }}</strong>
            </div>
          </div>
