        <b-card class="h-100">
          <h5 class="font-weight-bold mb-3">ความคืบหน้า Checklist</h5>
          <b-progress :max="100" height="1.4rem" class="mb-2" show-progress animated>
            <b-progress-bar :value="overview.checklistPercent" variant="warning">
              {{ overview.checklistPercent }}%
            </b-progress-bar>
          </b-progress>
          <p class="text-muted mb-3">
            เสร็จสิ้น {{ overview.checklistCompleted }} จาก {{ overview.checklistTotal }} รายการ
          </p>
          <b-button variant="outline-warning" size="sm" :to="{ name: 'checklist', query: { tab: 'progress' } }">
            ดู Checklist ทั้งหมด
