        <menu-card
          title="เลือกโรงพยาบาล"
          description="เลือกจังหวัดและโรงพยาบาลสำหรับตรวจสุขภาพ"
          icon="building"
          variant="danger"
          :to="{ name: 'choose_hospital' }"
        />
      </b-col>
      <b-col cols="12" md="6" lg="4" class="mb-3">
        <menu-card
          title="ข้อมูลพนักงาน"
          description="ค้นหา ตรวจสอบ และดูสรุปผลรายโรงพยาบาล"
          icon="card-list"
          variant="primary"
          :to="{ name: 'summary' }"
        />
      </b-col>
      <b-col cols="12" md="6" lg="4" class="mb-3">
        <menu-card
          :title="`แบบประเมินความพึงพอใจ ${yearBE}`"
          description="ประเมินการให้บริการและติดตาม Checklist"
          icon="card-checklist"
          variant="warning"
          :to="{ name: 'checklist' }"
          :locked="!isSurveyOpen"
          locked-text="ยังไม่ถึงช่วงเวลาทำแบบประเมิน..."
        />
      </b-col>
      <b-col cols="12" md="6" lg="4" class="mb-3">
        <menu-card
          title="Export"
          description="ดาวน์โหลดข้อมูลเป็นไฟล์ CSV"
          icon="person-lines-fill"
          variant="success"
          :to="{ name: 'export' }"
          :locked="!isAdmin"
          locked-text="สำหรับ Admin"
        />
      </b-col>
      <b-col cols="12" md="6" lg="4" class="mb-3">
        <menu-card
          title="ข้อมูลแบบประเมิน / จัดการ Checklist"
          description="ดูผลแบบประเมิน เพิ่ม แก้ไข ลบ รายการ Checklist"
          icon="journal-check"
          variant="info"
          :to="{ name: 'db_checklist' }"
          :locked="!isAdmin"
          locked-text="สำหรับ Admin"
        />
      </b-col>
    </b-row>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import StatCard from "../../components/StatCard.vue";
import MenuCard from "../../components/MenuCard.vue";
import StatusBadge from "../../components/StatusBadge.vue";

export default {
  name: "Home",
  components: { StatCard, MenuCard, StatusBadge },
  mixins: [common],
  computed: {
    ...mapGetters([
      "overview",
      "yearBE",
      "currentUser",
      "myParticipant",
      "isAdmin",
      "isSurveyOpen",
      "statusOptions",
    ]),
    counts() {
      return this.overview.counts;
    },
    hasHospital() {
      return !!(this.myParticipant && this.myParticipant.hospitalId);
    },
    legend() {
      const countOf = {
        completed: this.counts.completed,
        in_progress: this.counts.inProgress,
        pending: this.counts.pending,
        cancelled: this.counts.cancelled,
      };
      return this.statusOptions
        .slice()
        .sort((a, b) => this.order(a.value) - this.order(b.value))
        .map((o) => ({ ...o, count: countOf[o.value] }));
    },
  },
  watch: {
    // กรณีอยู่หน้า Home อยู่แล้วถูก guard ส่งกลับมา component จะไม่ mount ซ้ำ จึงต้องเฝ้า query
    "$route.query.denied"() {
      this.checkDenied();
    },
  },
  mounted() {
    this.checkDenied();
  },
  methods: {
    checkDenied() {
      if (!this.$route.query.denied) return;
      this.notify("ไม่มีสิทธิ์เข้าถึง", "หน้านี้สำหรับผู้ดูแลระบบ (Admin) เท่านั้น", "warning");
      this.replaceRoute({ name: "Home" });
    },
    order(value) {
      return ["completed", "in_progress", "pending", "cancelled"].indexOf(value);
    },
  },
};
</script>

