// src/mixins/exporter.js
// เตรียมข้อมูลจาก Vuex Store (action prepareExport) แล้วดาวน์โหลดเป็น CSV
import common from "./common";
import { downloadCsv } from "../utils/csv";

export default {
  mixins: [common],
  data() {
    return {
      exporting: false,
    };
  },
  methods: {
    async exportDataset(type, params = {}) {
      if (this.exporting) return null;
      this.exporting = true;
      try {
        const result = await this.$store.dispatch("prepareExport", { type, ...params });
        downloadCsv(result.filename, result.columns, result.rows);
        this.notify("ดาวน์โหลดสำเร็จ", `สร้างไฟล์ ${result.filename} (${result.total} รายการ)`, "success");
        return result;
      } catch (error) {
        this.notifyError(error, "ดาวน์โหลดไม่สำเร็จ");
        return null;
      } finally {
        this.exporting = false;
      }
    },
  },
};
