/* ==========================================================================
 * 1) Helpers
 * ======================================================================== */
const pad2 = (n) => String(n).padStart(2, "0");
const pad3 = (n) => String(n).padStart(3, "0");
const toIsoDate = (date) =>
  `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
const todayIso = () => toIsoDate(new Date());
const nowIso = () => new Date().toISOString();
const nextId = (list) => list.reduce((max, item) => Math.max(max, item.id), 0) + 1;
const percentOf = (part, whole) => (whole > 0 ? Math.round((part / whole) * 100) : 0);
const orDash = (value) =>
  value === null || value === undefined || value === "" ? "-" : value;
const isBlank = (value) =>
  value === null || value === undefined || String(value).trim() === "";

const buildError = (message, errors) => {
  const error = new Error(message);
  if (errors) error.errors = errors;
  return error;
};

/**
 * จำลองการเรียก API: หน่วงเวลา แล้วรัน handler
 * - ถ้าเปิดโหมด "จำลอง Error" (settings.simulateError) จะ reject ทุกครั้ง
 * - handler ที่ throw จะกลายเป็น Promise reject (ไม่มี Unhandled error)
 */
const mockRequest = (state, handler, delay = 500, options = {}) =>
  new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        if (state.settings.simulateError && !options.ignoreSimulatedError) {
          throw buildError("จำลองข้อผิดพลาดของระบบ กรุณาลองใหม่อีกครั้ง");
        }
        resolve(handler());
      } catch (error) {
        reject(error);
      }
    }, delay);
  });

