// สถานะเริ่มต้นของ Checklist ในแต่ละโรงพยาบาล (key = hospitalId)
const CHECKLIST_PROGRESS = {
  1: ["completed", "completed", "completed", "in_progress", "pending"],
  2: ["completed", "completed", "in_progress", "pending", "pending"],
  4: ["completed", "in_progress", "pending", "pending", "cancelled"],
  6: ["completed", "pending", "pending", "pending", "pending"],
};

const buildChecklists = (year) => {
  const list = [];
  let id = 1;
  Object.keys(CHECKLIST_PROGRESS).forEach((hospitalId) => {
    CHECKLIST_PROGRESS[hospitalId].forEach((status, index) => {
      const template = CHECKLIST_TEMPLATES[index];
      const stamp = `${year}-11-0${index + 1}T03:00:00.000Z`;
      const done = status === "completed";
      list.push({
        id,
        code: `CL-${pad3(id)}`,
        hospitalId: Number(hospitalId),
        title: template.title,
        description: template.description,
        status,
        completed: done,
        completedAt: done ? stamp : null,
        updatedAt: status === "pending" ? null : stamp,
      });
      id += 1;
    });
  });
  return list;
};

const rate = (values) =>
  values.reduce((acc, value, index) => {
    acc[`q${index + 1}`] = value;
    return acc;
  }, {});

