/* ==========================================================================
 * 4) Store
 * ======================================================================== */
export const store = new Vuex.Store({
  state: createInitialState(),

  /* ------------------------------------------------------------------ *
   * GETTERS
   * ------------------------------------------------------------------ */
  getters: {
    // ----- ระบบ / ผู้ใช้ -----
    currentYear: (state) => state.year,
    yearBE: (state) => state.year + 543,
    yearOptions: (state) =>
      Array.from({ length: 6 }, (_, i) => state.year - i).map((y) => ({ value: y, text: `${y + 543}` })),
    currentUser: (state) => state.currentUser,
    isAuthenticated: (state) => !!state.currentUser.employeeCode,
    isAdmin: (state) => state.currentUser.role === "admin",
    isLoading: (state) => state.loading.app,
    settings: (state) => state.settings,
    isHospitalSelectionOpen: (state) => todayIso() <= state.settings.hospitalDeadline,
    isSurveyOpen: (state) =>
      todayIso() >= state.settings.surveyOpenFrom && todayIso() <= state.settings.surveyOpenUntil,

    // ----- Master data -----
    statusOptions: (state) => state.statusOptions,
    statusMeta: (state) => (value) =>
      state.statusOptions.find((o) => o.value === value) || { value, text: "ไม่ทราบสถานะ", variant: "light" },
    contacts: (state) => state.contacts,
    exportDatasets: (state) => state.exportDatasets,
    surveyOptions: (state) => state.surveyOptions,
    surveyQuestions: (state) => state.surveyQuestions,
    provinces: (state) => state.provinces,
    provinceOptions: (state) => state.provinces.map((p) => ({ value: p, text: p })),
    provincesWithHospitals: (state, getters) =>
      state.provinces.filter((p) => getters.activeHospitals.some((h) => h.province === p)),
    programs: (state) => state.programs,
    programById: (state) => (id) => state.programs.find((p) => p.id === id) || null,
    hospitals: (state) => state.hospitals,
    activeHospitals: (state) => state.hospitals.filter((h) => h.active),
    hospitalById: (state) => (id) => state.hospitals.find((h) => h.id === id) || null,
    hospitalOptions: (state) => state.hospitals.map((h) => ({ value: h.id, text: h.nameTh })),

    // ----- ผู้เข้ารับการตรวจ -----
    participantsByYear: (state) => (year) =>
      state.participants.filter((p) => p.year === year).map((p) => enrichParticipant(p, state)),
    participantByCode: (state) => (code, year) => {
      const found = state.participants.find((p) => p.employeeCode === code && p.year === year);
      return found ? enrichParticipant(found, state) : null;
    },
    myParticipant: (state, getters) =>
      getters.participantByCode(state.currentUser.employeeCode, state.year),
    participantCounts: (state) => (year) => {
      const rows = state.participants.filter((p) => p.year === year);
      const eligible = rows.filter((p) => p.status !== "cancelled");
      const selected = eligible.filter((p) => p.hospitalId !== null).length;
      return {
        ...countByStatus(rows),
        eligible: eligible.length,
        selected,
        notSelected: eligible.length - selected,
        surveyDone: rows.filter((p) => state.surveys.some((s) => s.participantId === p.id)).length,
      };
    },

    // ----- สรุป -----
    summaryByHospital: (state) => (year) => {
      const rows = state.participants.filter((p) => p.year === year);
      const groups = state.hospitals
        .map((h) => ({ key: h.id, hospitalId: h.id, name: h.nameTh, province: h.province, items: rows.filter((p) => p.hospitalId === h.id) }))
        .filter((g) => g.items.length > 0);
      const unselected = rows.filter((p) => p.hospitalId === null);
      if (unselected.length > 0) {
        groups.push({ key: "none", hospitalId: null, name: "ยังไม่เลือกโรงพยาบาล", province: "", items: unselected });
      }
      return groups.map((g) => ({
        key: g.key,
        hospitalId: g.hospitalId,
        name: g.name,
        province: g.province,
        ...countByStatus(g.items),
      }));
    },
    summaryByProgram: (state) => (year) => {
      const rows = state.participants.filter((p) => p.year === year);
      return state.programs
        .map((program) => ({
          key: program.id,
          programId: program.id,
          name: program.name,
          ...countByStatus(rows.filter((p) => p.programId === program.id)),
        }))
        .filter((r) => r.total > 0);
    },

    // ----- Checklist -----
    checklistRows: (state) =>
      state.checklists.map((c) => {
        const hospital = state.hospitals.find((h) => h.id === c.hospitalId);
        return { ...c, hospitalName: hospital ? hospital.nameTh : "ไม่พบโรงพยาบาล" };
      }),
    checklistById: (state) => (id) => state.checklists.find((c) => c.id === id) || null,
    checklistStats: (state) => (hospitalId = null) => {
      const items = hospitalId ? state.checklists.filter((c) => c.hospitalId === hospitalId) : state.checklists;
      return countByStatus(items);
    },
    nextChecklistCode: (state) => {
      const max = state.checklists.reduce((acc, c) => {
        const match = /^CL-(\d+)$/.exec(c.code);
        return match ? Math.max(acc, Number(match[1])) : acc;
      }, 0);
      return `CL-${pad3(max + 1)}`;
    },
    validateChecklistForm: (state) => (form, editingId = null) => {
      const errors = {};
      const code = String(form.code || "").trim().toUpperCase();
      if (!code) errors.code = "กรุณากรอกรหัส";
      else if (!/^CL-\d{3,}$/.test(code)) errors.code = "รูปแบบรหัสไม่ถูกต้อง (ตัวอย่าง CL-001)";
      else if (state.checklists.some((c) => c.code === code && c.id !== editingId)) errors.code = "รหัสนี้ถูกใช้แล้ว";

      const hospitalId = Number(form.hospitalId);
      if (isBlank(form.hospitalId)) errors.hospitalId = "กรุณาเลือกโรงพยาบาล";
      else if (!state.hospitals.some((h) => h.id === hospitalId)) errors.hospitalId = "ไม่พบโรงพยาบาลที่เลือก";

      const title = String(form.title || "").trim();
      if (!title) errors.title = "กรุณากรอกชื่อรายการ";
      else if (title.length < 3) errors.title = "ชื่อรายการต้องมีอย่างน้อย 3 ตัวอักษร";
      else if (title.length > 120) errors.title = "ชื่อรายการต้องไม่เกิน 120 ตัวอักษร";
      else if (!errors.hospitalId && state.checklists.some((c) => c.id !== editingId && c.hospitalId === hospitalId && c.title.trim() === title)) {
        errors.title = "มีรายการนี้ในโรงพยาบาลนี้แล้ว";
      }

      if (String(form.description || "").length > 500) errors.description = "รายละเอียดต้องไม่เกิน 500 ตัวอักษร";
      if (!state.statusOptions.some((o) => o.value === form.status)) errors.status = "สถานะไม่ถูกต้อง";
      return errors;
    },

    // ----- แบบประเมินความพึงพอใจ -----
    surveyRows: (state) => (year) =>
      state.surveys
        .filter((s) => s.year === year)
        .map((s) => {
          const hospital = state.hospitals.find((h) => h.id === s.hospitalId);
          return {
            ...s,
            hospitalName: hospital ? hospital.nameTh : "",
            average: averageRating(s.ratings, state.surveyQuestions),
          };
        }),
    surveyStats: (state) => (year) => {
      const list = state.surveys.filter((s) => s.year === year);
      const me = state.participants.find((p) => p.employeeCode === state.currentUser.employeeCode && p.year === year);
      return {
        total: list.length,
        respondents: new Set(list.map((s) => s.participantId)).size,
        mine: me ? list.filter((s) => s.participantId === me.id).length : 0,
      };
    },
    surveyAverages: (state) => (year) =>
      state.surveyQuestions.map((q) => {
        const values = state.surveys
          .filter((s) => s.year === year)
          .map((s) => s.ratings[q.id])
          .filter((v) => Number.isFinite(v));
        const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
        return { id: q.id, no: q.no, label: q.label, count: values.length, average: Math.round(avg * 100) / 100 };
      }),
    mySurvey: (state, getters) => {
      const me = getters.myParticipant;
      if (!me) return null;
      return state.surveys.find((s) => s.participantId === me.id) || null;
    },
    validateSurveyForm: (state) => (form) => {
      const errors = {};
      const required = "กรุณาเลือกคำตอบ";
      const options = state.surveyOptions;
      const check = (key, list) => {
        if (!list.some((o) => o.value === form[key])) errors[key] = required;
      };
      check("sex", options.sex);
      check("ageRange", options.ageRange);
      check("fasting", options.yesNo);
      check("sleep", options.yesNo);
      check("hasHealthIssue", options.healthIssue);
      if (form.hasHealthIssue === "มี" && isBlank(form.healthIssueDetail)) {
        errors.healthIssueDetail = "กรุณาระบุปัญหาสุขภาพ";
      }
      check("smoking", options.smoking);
      check("drinking", options.drinking);
      check("exercise", options.exercise);
      state.surveyQuestions.forEach((q) => {
        const value = form.ratings ? form.ratings[q.id] : null;
        if (!Number.isInteger(value) || value < 1 || value > 5) errors[q.id] = "กรุณาให้คะแนน 1-5 ดาว";
      });
      check("waitDoctor", options.waitDoctor);
      check("returnNext", options.returnNext);
      check("resultSatisfied", options.resultSatisfied);
      if (String(form.comment || "").length > 500) errors.comment = "ข้อเสนอแนะต้องไม่เกิน 500 ตัวอักษร";
      return errors;
    },

    // ----- Home -----
    overview: (state, getters) => {
      const counts = getters.participantCounts(state.year);
      const checklist = getters.checklistStats(null);
      const survey = getters.surveyStats(state.year);
      return {
        hospitalCount: getters.activeHospitals.length,
        participantCount: counts.total,
        counts,
        checklistTotal: checklist.total,
        checklistCompleted: checklist.completed,
        checklistPercent: checklist.percent,
        surveyCount: survey.total,
      };
    },
  },

  /* ------------------------------------------------------------------ *
   * MUTATIONS (แก้ไข state เท่านั้น)
   * ------------------------------------------------------------------ */
  mutations: {
    SET_LOADING(state, { key, value }) {
      Vue.set(state.loading, key, value);
    },
    SET_LOADED(state, value) {
      state.loaded = !!value;
    },
    SET_ROLE(state, role) {
      if (role === "admin" || role === "employee") state.currentUser.role = role;
    },
    SET_SIMULATE_ERROR(state, value) {
      state.settings.simulateError = !!value;
    },
    RESET_DATA(state) {
      // รีเซ็ตเฉพาะข้อมูลจำลอง คงบทบาทและโหมดจำลอง Error ของ session ไว้
      const fresh = createInitialState();
      fresh.currentUser.role = state.currentUser.role;
      fresh.settings.simulateError = state.settings.simulateError;
      Object.assign(state, fresh, { loaded: true });
    },

    SET_PARTICIPANT_HOSPITAL(state, { participantId, hospitalId }) {
      const participant = state.participants.find((p) => p.id === participantId);
      if (participant) participant.hospitalId = hospitalId;
    },

    ADD_CHECKLIST(state, item) {
      state.checklists.push(item);
    },
    UPDATE_CHECKLIST(state, item) {
      const index = state.checklists.findIndex((c) => c.id === item.id);
      if (index !== -1) state.checklists.splice(index, 1, item);
    },
    DELETE_CHECKLIST(state, id) {
      const index = state.checklists.findIndex((c) => c.id === id);
      if (index !== -1) state.checklists.splice(index, 1);
    },
    SET_CHECKLIST_STATUS(state, { id, status, at }) {
      const item = state.checklists.find((c) => c.id === id);
      if (!item) return;
      item.status = status;
      item.completed = status === "completed";
      item.completedAt = status === "completed" ? at : null;
      item.updatedAt = at;
    },

    ADD_SURVEY(state, survey) {
      state.surveys.push(survey);
    },
  },

  /* ------------------------------------------------------------------ *
   * ACTIONS (จำลอง asynchronous ด้วย Promise + setTimeout)
   * ------------------------------------------------------------------ */
  actions: {
    initApp({ commit }) {
      commit("SET_LOADING", { key: "app", value: true });
      return new Promise((resolve) => {
        setTimeout(() => {
          commit("SET_LOADED", true);
          commit("SET_LOADING", { key: "app", value: false });
          resolve(true);
        }, 500);
      });
    },

    resetData({ commit, state }) {
      return mockRequest(
        state,
        () => {
          commit("RESET_DATA");
          return true;
        },
        400,
        { ignoreSimulatedError: true }
      );
    },

    selectHospital({ commit, state, getters }, { participantId, hospitalId }) {
      return mockRequest(
        state,
        () => {
          const participant = state.participants.find((p) => p.id === participantId);
          if (!participant) throw buildError("ไม่พบข้อมูลที่ต้องการ");
          if (participant.status === "cancelled") throw buildError("คุณไม่มีสิทธิ์ตรวจสุขภาพ");
          if (!getters.isAdmin) {
            if (!getters.isHospitalSelectionOpen) throw buildError("หมดเวลาเลือกโรงพยาบาล ติดต่อ HR");
            if (participant.status === "completed") throw buildError("เข้ารับการตรวจแล้ว ไม่สามารถเปลี่ยนโรงพยาบาลได้");
          }
          const hospital = getters.hospitalById(hospitalId);
          if (!hospital) throw buildError("ไม่พบโรงพยาบาลที่เลือก");
          if (!hospital.active) throw buildError("โรงพยาบาลนี้ปิดให้บริการ กรุณาเลือกโรงพยาบาลอื่น");
          commit("SET_PARTICIPANT_HOSPITAL", { participantId, hospitalId });
          return getters.participantByCode(participant.employeeCode, participant.year);
        },
        600
      );
    },

    changeChecklistStatus({ commit, state }, { id, status }) {
      return mockRequest(
        state,
        () => {
          const item = state.checklists.find((c) => c.id === id);
          if (!item) throw buildError("ไม่พบข้อมูลที่ต้องการ");
          if (!state.statusOptions.some((o) => o.value === status)) throw buildError("สถานะไม่ถูกต้อง");
          if (item.status !== status) commit("SET_CHECKLIST_STATUS", { id, status, at: nowIso() });
          return item;
        },
        400
      );
    },

    saveChecklist({ commit, state, getters }, form) {
      return mockRequest(
        state,
        () => {
          const editingId = form.id === undefined || form.id === null ? null : form.id;
          const existing = editingId === null ? null : state.checklists.find((c) => c.id === editingId);
          if (editingId !== null && !existing) throw buildError("ไม่พบข้อมูลที่ต้องการ");

          const errors = getters.validateChecklistForm(form, editingId);
          if (Object.keys(errors).length > 0) throw buildError("กรุณากรอกข้อมูลให้ถูกต้อง", errors);

          const at = nowIso();
          const done = form.status === "completed";
          const item = {
            id: editingId === null ? nextId(state.checklists) : editingId,
            code: String(form.code).trim().toUpperCase(),
            hospitalId: Number(form.hospitalId),
            title: String(form.title).trim(),
            description: String(form.description || "").trim(),
            status: form.status,
            completed: done,
            completedAt: done ? (existing && existing.completedAt) || at : null,
            updatedAt: at,
          };
          commit(editingId === null ? "ADD_CHECKLIST" : "UPDATE_CHECKLIST", item);
          return item;
        },
        600
      );
    },

    deleteChecklist({ commit, state }, id) {
      return mockRequest(
        state,
        () => {
          if (!state.checklists.some((c) => c.id === id)) throw buildError("ไม่พบข้อมูลที่ต้องการ");
          commit("DELETE_CHECKLIST", id);
          return true;
        },
        500
      );
    },

    submitSurvey({ commit, state, getters }, form) {
      return mockRequest(
        state,
        () => {
          const me = getters.myParticipant;
          if (!me) throw buildError("คุณไม่มีสิทธิ์ตรวจสุขภาพ");
          if (!me.hospitalId) throw buildError("กรุณาเลือกโรงพยาบาลก่อนทำแบบประเมิน");
          if (!getters.isSurveyOpen) throw buildError("ยังไม่ถึงเวลาบันทึกแบบประเมิน");
          if (getters.mySurvey) throw buildError("คุณทำแบบประเมินของปีนี้แล้ว");

          const errors = getters.validateSurveyForm(form);
          if (Object.keys(errors).length > 0) throw buildError("กรุณากรอกแบบประเมินให้ครบถ้วน", errors);

          const ratings = {};
          state.surveyQuestions.forEach((q) => {
            ratings[q.id] = form.ratings[q.id];
          });
          const survey = {
            id: nextId(state.surveys),
            year: state.year,
            participantId: me.id,
            sex: form.sex,
            ageRange: form.ageRange,
            hospitalId: me.hospitalId,
            fasting: form.fasting,
            sleep: form.sleep,
            hasHealthIssue: form.hasHealthIssue,
            healthIssueDetail: form.hasHealthIssue === "มี" ? String(form.healthIssueDetail).trim() : "",
            smoking: form.smoking,
            drinking: form.drinking,
            exercise: form.exercise,
            ratings,
            waitDoctor: form.waitDoctor,
            returnNext: form.returnNext,
            resultSatisfied: form.resultSatisfied,
            comment: String(form.comment || "").trim(),
            createdAt: nowIso(),
          };
          commit("ADD_SURVEY", survey);
          return survey;
        },
        700
      );
    },

    prepareExport({ state, getters }, params = {}) {
      return mockRequest(state, () => buildExportResult(params.type, state, getters, params), 400);
    },
  },
});

export default store;
