<template>
  <div class="container-xl py-4">
    <page-header
      icon="journal-check"
      variant="warning"
      title="จัดการข้อมูล"
      subtitle="ดูผลแบบประเมินความพึงพอใจ และเพิ่ม แก้ไข ลบ รายการ Checklist"
    />

    <b-card no-body>
      <b-tabs card>
        <!-- ================= ข้อมูลแบบประเมิน ================= -->
        <b-tab title="ข้อมูลแบบประเมินความพึงพอใจ" active>
          <b-row class="align-items-center mb-3">
            <b-col cols="12" md="4" lg="3" class="mb-2 mb-md-0">
              <b-input-group size="sm" prepend="ประจำปี">
                <b-form-select v-model="surveyYear" :options="yearOptions" @change="onSurveyYearChange"></b-form-select>
              </b-input-group>
            </b-col>
            <b-col cols="12" md="8" lg="9" class="text-md-right">
              <span class="small mr-3">พบ <strong>{{ surveyRowsData.length }}</strong> รายการ</span>
              <b-button
                variant="outline-dark"
                size="sm"
                :disabled="exporting || surveyRowsData.length === 0"
                @click="downloadSurvey"
              >
                <b-spinner v-if="exporting" small class="mr-1"></b-spinner>
                <b-icon v-else icon="download" class="mr-1"></b-icon>
                Download CSV
              </b-button>
            </b-col>
          </b-row>

          <b-overlay :show="surveyBusy" rounded="sm" spinner-small>
            <!-- คะแนนเฉลี่ยรายข้อ -->
            <div v-if="surveyRowsData.length > 0" class="avg-box mb-3">
              <div class="font-weight-bold mb-2">คะแนนเฉลี่ยรายข้อ (เต็ม 5)</div>
              <b-row>
                <b-col v-for="a in surveyAveragesList" :key="a.id" cols="12" md="6" class="mb-1">
                  <div class="d-flex align-items-center">
                    <span class="avg-label text-truncate" :title="`${a.no} ${a.label}`">{{ a.no }} {{ a.label }}</span>
                    <b-progress :max="5" height="0.9rem" class="flex-grow-1 mx-2">
                      <b-progress-bar :value="a.average" :variant="avgVariant(a.average)"></b-progress-bar>
                    </b-progress>
                    <strong class="avg-value">{{ a.average.toFixed(2) }}</strong>
                  </div>
                </b-col>
              </b-row>
            </div>

            <b-table
              :items="surveyRowsData"
              :fields="surveyFields"
              head-variant="dark"
              small
              bordered
              striped
              hover
              responsive
              show-empty
              empty-text="ยังไม่มีข้อมูลแบบประเมินในปีนี้"
              class="f_s_90p"
            >
              <template #cell(no)="data">{{ data.index + 1 }}</template>
              <template #cell(average)="data">
                <b-badge :variant="avgVariant(data.value)">{{ data.value.toFixed(2) }}</b-badge>
              </template>
              <template #cell(healthIssueDetail)="data">{{ display(data.value) }}</template>
              <template #cell(comment)="data">{{ display(data.value) }}</template>
              <template #cell(createdAt)="data">{{ formatDateTime(data.value) }}</template>
              <template v-for="q in surveyQuestions" #[`cell(${q.id})`]="data">
                {{ data.item.ratings[q.id] }}
              </template>
            </b-table>
          </b-overlay>
        </b-tab>

        <!-- ================= จัดการ Checklist (CRUD) ================= -->
        <b-tab title="จัดการรายการ Checklist">
          <b-row class="align-items-center mb-3">
            <b-col cols="12" lg="3" class="mb-2 mb-lg-0">
              <b-input-group size="sm">
                <b-input-group-prepend is-text><b-icon icon="search"></b-icon></b-input-group-prepend>
                <b-form-input v-model="filter" type="search" placeholder="ค้นหารายการ"></b-form-input>
              </b-input-group>
            </b-col>
            <b-col cols="6" lg="3" class="mb-2 mb-lg-0">
              <b-form-select v-model="hospitalFilter" :options="hospitalFilterOptions" size="sm"></b-form-select>
            </b-col>
            <b-col cols="6" lg="2" class="mb-2 mb-lg-0">
              <b-form-select v-model="statusFilter" :options="statusFilterOptions" size="sm"></b-form-select>
            </b-col>
            <b-col cols="12" lg="4" class="text-lg-right">
              <b-button variant="primary" size="sm" @click="openAdd">
                <b-icon icon="plus-circle" class="mr-1"></b-icon>เพิ่มรายการ
              </b-button>
            </b-col>
          </b-row>

          <b-table
            :items="checklistItems"
            :fields="checklistFields"
            :filter="filter"
            :current-page="currentPage"
            :per-page="perPage"
            head-variant="dark"
            small
            bordered
            striped
            hover
            responsive
            show-empty
            class="f_s_90p"
            @filtered="onFiltered"
          >
            <template #empty>
              <empty-state
                icon="journal-x"
                title="ยังไม่มีรายการ Checklist"
                description="กดปุ่ม “เพิ่มรายการ” เพื่อสร้างรายการแรก"
              >
                <b-button variant="primary" size="sm" @click="openAdd">เพิ่มรายการ</b-button>
              </empty-state>
            </template>
            <template #emptyfiltered>
              <empty-state icon="search" title="ไม่พบรายการที่ตรงกับเงื่อนไข" description="ลองเปลี่ยนคำค้นหาหรือตัวกรอง" />
            </template>
            <template #cell(title)="data">
              <div class="font-weight-bold">{{ data.value }}</div>
              <small class="text-muted">{{ display(data.item.description) }}</small>
            </template>
            <template #cell(status)="data"><status-badge :status="data.value" /></template>
            <template #cell(updatedAt)="data">{{ formatDateTime(data.value) }}</template>
            <template #cell(actions)="data">
              <b-button-group size="sm">
                <b-button variant="outline-info" title="ดูรายละเอียด" @click="openView(data.item)">
                  <b-icon icon="eye"></b-icon>
                </b-button>
                <b-button variant="outline-primary" title="แก้ไข" @click="openEdit(data.item)">
                  <b-icon icon="pencil-square"></b-icon>
                </b-button>
                <b-button
                  variant="outline-danger"
                  title="ลบ"
                  :disabled="deletingId === data.item.id"
                  @click="confirmDelete(data.item)"
                >
                  <b-spinner v-if="deletingId === data.item.id" small></b-spinner>
                  <b-icon v-else icon="trash"></b-icon>
                </b-button>
              </b-button-group>
            </template>
          </b-table>

          <div v-if="totalRows > perPage" class="d-flex justify-content-between align-items-center">
            <small class="text-muted">ทั้งหมด {{ totalRows }} รายการ</small>
            <b-pagination v-model="currentPage" :total-rows="totalRows" :per-page="perPage" size="sm" class="mb-0" />
          </div>
        </b-tab>
      </b-tabs>
    </b-card>

    <!-- ===== Modal: เพิ่ม / แก้ไข ===== -->
    <b-modal
      id="modal-checklist-form"
      :title="form.id === null ? 'เพิ่มรายการ Checklist' : 'แก้ไขรายการ Checklist'"
      :ok-title="form.id === null ? 'เพิ่มรายการ' : 'บันทึกการแก้ไข'"
      cancel-title="ยกเลิก"
      ok-variant="primary"
      :busy="saving"
      no-close-on-backdrop
      no-close-on-esc
      centered
      @ok="onSave"
    >
      <b-form novalidate @submit.prevent="onSave">
        <b-form-group label="รหัส" label-for="f-code" :state="fieldState('code')" :invalid-feedback="errors.code">
          <b-form-input id="f-code" v-model="form.code" :state="fieldState('code')" placeholder="CL-001" maxlength="20"></b-form-input>
        </b-form-group>
        <b-form-group label="โรงพยาบาล" label-for="f-hospital" :state="fieldState('hospitalId')" :invalid-feedback="errors.hospitalId">
          <b-form-select id="f-hospital" v-model="form.hospitalId" :options="hospitalOptions" :state="fieldState('hospitalId')">
            <template #first>
              <b-form-select-option :value="null" disabled>-- เลือกโรงพยาบาล --</b-form-select-option>
            </template>
          </b-form-select>
        </b-form-group>
        <b-form-group label="ชื่อรายการ" label-for="f-title" :state="fieldState('title')" :invalid-feedback="errors.title">
          <b-form-input id="f-title" v-model="form.title" :state="fieldState('title')" maxlength="120"></b-form-input>
        </b-form-group>
        <b-form-group label="รายละเอียด" label-for="f-desc" :state="fieldState('description')" :invalid-feedback="errors.description">
          <b-form-textarea id="f-desc" v-model="form.description" rows="3" max-rows="6" :state="fieldState('description')"></b-form-textarea>
        </b-form-group>
        <b-form-group label="สถานะ" label-for="f-status" :state="fieldState('status')" :invalid-feedback="errors.status" class="mb-0">
          <b-form-select id="f-status" v-model="form.status" :options="statusOptions" :state="fieldState('status')"></b-form-select>
        </b-form-group>
      </b-form>
    </b-modal>

    <!-- ===== Modal: ดูรายละเอียด ===== -->
    <b-modal id="modal-checklist-view" title="รายละเอียดรายการ Checklist" ok-only ok-title="ปิด" ok-variant="secondary" centered>
      <b-alert v-if="!viewItem" show variant="warning" class="mb-0">ไม่พบข้อมูลที่ต้องการ</b-alert>
      <dl v-else class="detail-list mb-0">
        <dt>รหัส</dt><dd>{{ viewItem.code }}</dd>
        <dt>โรงพยาบาล</dt><dd>{{ viewItem.hospitalName }}</dd>
        <dt>ชื่อรายการ</dt><dd>{{ viewItem.title }}</dd>
        <dt>รายละเอียด</dt><dd>{{ display(viewItem.description) }}</dd>
        <dt>สถานะ</dt><dd><status-badge :status="viewItem.status" /></dd>
        <dt>วันที่เสร็จสิ้น</dt><dd>{{ formatDateTime(viewItem.completedAt) }}</dd>
        <dt>อัปเดตล่าสุด</dt><dd>{{ formatDateTime(viewItem.updatedAt) }}</dd>
      </dl>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import exporter from "../../mixins/exporter";
import PageHeader from "../../components/PageHeader.vue";
import EmptyState from "../../components/EmptyState.vue";
import StatusBadge from "../../components/StatusBadge.vue";

// ฟอร์มเปล่า (ข้อมูลชั่วคราวของฟอร์ม)
const blankForm = (code = "") => ({
  id: null,
  code,
  hospitalId: null,
  title: "",
  description: "",
  status: "pending",
});

export default {
  name: "DbChecklist",
  components: { PageHeader, EmptyState, StatusBadge },
  mixins: [common, exporter],
  data() {
    return {
      // ---- แท็บข้อมูลแบบประเมิน ----
      surveyYear: this.$store.getters.currentYear,
      surveyBusy: false,
      // ---- แท็บ CRUD ----
      filter: "",
      hospitalFilter: null,
      statusFilter: null,
      currentPage: 1,
      perPage: 8,
      filteredCount: null,
      form: blankForm(),
      submitted: false,
      saving: false,
      deletingId: null,
      viewId: null,
      checklistFields: [
        { key: "code", label: "รหัส", sortable: true },
        { key: "hospitalName", label: "โรงพยาบาล", sortable: true },
        { key: "title", label: "รายการ", sortable: true },
        { key: "status", label: "สถานะ", sortable: true },
        { key: "updatedAt", label: "อัปเดตล่าสุด", sortable: true },
        { key: "actions", label: "จัดการ", thClass: "text-center", tdClass: "text-center" },
      ],
    };
  },
  computed: {
    ...mapGetters([
      "yearOptions",
      "surveyRows",
      "surveyAverages",
      "surveyQuestions",
      "checklistRows",
      "checklistById",
      "hospitalOptions",
      "statusOptions",
      "nextChecklistCode",
    ]),
    // ---- แบบประเมิน ----
    surveyRowsData() {
      return this.surveyRows(this.surveyYear);
    },
    surveyAveragesList() {
      return this.surveyAverages(this.surveyYear);
    },
    surveyFields() {
      const questionFields = this.surveyQuestions.map((q) => ({
        key: q.id,
        label: `${q.no} ${q.label}`,
        class: "text-center",
        thStyle: { minWidth: "130px" },
      }));
      return [
        { key: "no", label: "ลำดับ" },
        { key: "sex", label: "เพศ" },
        { key: "ageRange", label: "อายุ" },
        { key: "hospitalName", label: "รพ." },
        { key: "fasting", label: "งดอาหารและเครื่องดื่ม (>= 12 ชม.)" },
        { key: "sleep", label: "นอนหลับพักผ่อนเพียงพอ (>= 6 ชม.)" },
        { key: "hasHealthIssue", label: "มีปัญหาสุขภาพใน 1 ปีที่ผ่านมา" },
        { key: "healthIssueDetail", label: "เพิ่มเติม" },
        { key: "smoking", label: "สูบบุหรี่" },
        { key: "drinking", label: "ดื่มสุรา" },
        { key: "exercise", label: "การออกกำลังกาย" },
      ]
        .concat(questionFields)
        .concat([
          { key: "average", label: "คะแนนเฉลี่ย", class: "text-center" },
          { key: "waitDoctor", label: "การรอพบแพทย์" },
          { key: "returnNext", label: "กลับมาตรวจในปีถัดไป" },
          { key: "resultSatisfied", label: "ความพอใจกับผลตรวจ" },
          { key: "comment", label: "ปัญหาหรือข้อเสนอแนะ" },
          { key: "createdAt", label: "วันที่บันทึก" },
        ]);
    },
    // ---- CRUD ----
    hospitalFilterOptions() {
      return [{ value: null, text: "ทุกโรงพยาบาล" }].concat(this.hospitalOptions);
    },
    statusFilterOptions() {
      return [{ value: null, text: "ทุกสถานะ" }].concat(
        this.statusOptions.map((o) => ({ value: o.value, text: o.text }))
      );
    },
    checklistItems() {
      return this.checklistRows.filter(
        (c) =>
          (this.hospitalFilter === null || c.hospitalId === this.hospitalFilter) &&
          (this.statusFilter === null || c.status === this.statusFilter)
      );
    },
    totalRows() {
      return this.filteredCount === null ? this.checklistItems.length : this.filteredCount;
    },
    errors() {
      return this.$store.getters.validateChecklistForm(this.form, this.form.id);
    },
    viewItem() {
      return this.viewId === null ? null : this.checklistRows.find((c) => c.id === this.viewId) || null;
    },
  },
  watch: {
    filter() {
      this.currentPage = 1;
    },
    hospitalFilter() {
      this.resetPaging();
    },
    statusFilter() {
      this.resetPaging();
    },
  },
  beforeDestroy() {
    clearTimeout(this.timer);
  },
  methods: {
    // ---------- แบบประเมิน ----------
    onSurveyYearChange() {
      this.surveyBusy = true;
      clearTimeout(this.timer);
      this.timer = setTimeout(() => {
        this.surveyBusy = false;
      }, 400);
    },
    avgVariant(value) {
      if (value >= 4) return "success";
      if (value >= 3) return "info";
      return "warning";
    },
    downloadSurvey() {
      return this.exportDataset("survey", { year: this.surveyYear });
    },
    // ---------- CRUD ----------
    resetPaging() {
      this.currentPage = 1;
      this.filteredCount = null;
    },
    onFiltered(items) {
      this.filteredCount = items.length;
      this.currentPage = 1;
    },
    fieldState(key) {
      if (!this.submitted) return null;
      return this.errors[key] ? false : null;
    },
    openAdd() {
      this.form = blankForm(this.nextChecklistCode);
      this.submitted = false;
      this.$bvModal.show("modal-checklist-form");
    },
    openEdit(item) {
      // สร้างสำเนาก่อนแก้ไข ไม่แก้ object จาก Store โดยตรง
      this.form = { ...blankForm(), ...item };
      this.submitted = false;
      this.$bvModal.show("modal-checklist-form");
    },
    openView(item) {
      this.viewId = item.id;
      this.$bvModal.show("modal-checklist-view");
    },
    async onSave(event) {
      if (event && event.preventDefault) event.preventDefault(); // กันไม่ให้ Modal ปิดก่อนบันทึกเสร็จ
      this.submitted = true;
      if (Object.keys(this.errors).length > 0 || this.saving) return;
      this.saving = true;
      const isNew = this.form.id === null;
      try {
        const saved = await this.$store.dispatch("saveChecklist", this.form);
        this.$bvModal.hide("modal-checklist-form");
        this.notify(
          "บันทึกสำเร็จ",
          isNew ? `เพิ่มรายการ "${saved.title}" เรียบร้อย` : `แก้ไขรายการ "${saved.title}" เรียบร้อย`,
          "success"
        );
      } catch (error) {
        this.notifyError(error, "บันทึกไม่สำเร็จ");
      } finally {
        this.saving = false;
      }
    },
    async confirmDelete(item) {
      const ok = await this.$bvModal.msgBoxConfirm(`ต้องการลบรายการ "${item.title}" ใช่หรือไม่? การลบไม่สามารถย้อนกลับได้`, {
        title: "ยืนยันการลบ",
        okVariant: "danger",
        okTitle: "ลบ",
        cancelTitle: "ยกเลิก",
        centered: true,
      });
      if (!ok) return;
      this.deletingId = item.id;
      try {
        await this.$store.dispatch("deleteChecklist", item.id);
        this.notify("ลบสำเร็จ", `ลบรายการ "${item.title}" เรียบร้อย`, "success");
      } catch (error) {
        this.notifyError(error, "ลบไม่สำเร็จ");
      } finally {
        this.deletingId = null;
      }
    },
  },
};
</script>

<style scoped>
.avg-box {
  background: #fafbfc;
  border: 1px solid #e6eaf0;
  border-radius: 0.7rem;
  padding: 0.9rem 1rem;
}
.avg-label {
  width: 46%;
  font-size: 0.85rem;
}
.avg-value {
  width: 2.8rem;
  text-align: right;
}
.detail-list dt {
  float: left;
  clear: left;
  width: 8.5rem;
  color: #6b7280;
  font-weight: 500;
}
.detail-list dd {
  margin-left: 9rem;
  margin-bottom: 0.6rem;
}
</style>
