<template>
  <div class="container-xl py-4">
    <page-header
      icon="person-lines-fill"
      variant="success"
      title="Export รายชื่อผู้เข้าตรวจสุขภาพ"
      subtitle="เลือกประเภทข้อมูลและเงื่อนไข จากนั้นสร้างหน้าตัวอย่างหรือดาวน์โหลดเป็นไฟล์ CSV"
    />

    <b-card class="mb-4">
      <b-row>
        <b-col cols="12" md="6" lg="4">
          <b-form-group label="ประเภทข้อมูล" label-for="ex-type">
            <b-form-select id="ex-type" v-model="type" :options="datasetOptions"></b-form-select>
          </b-form-group>
        </b-col>

        <b-col v-if="usesFilter('contact')" cols="12" md="6" lg="4">
          <b-form-group label="ผู้ติดต่อ" label-for="ex-contact">
            <b-form-select id="ex-contact" v-model="contactId" :options="contacts"></b-form-select>
          </b-form-group>
        </b-col>

        <b-col v-if="usesFilter('year')" cols="12" md="6" lg="4">
          <b-form-group label="ประจำปี" label-for="ex-year">
            <b-form-select id="ex-year" v-model="year" :options="yearOptions"></b-form-select>
          </b-form-group>
        </b-col>

        <b-col v-if="usesFilter('province')" cols="12" md="6" lg="4">
          <b-form-group label="จังหวัด" label-for="ex-province">
            <b-form-select id="ex-province" v-model="province" :options="provinceChoices" @change="onProvinceChange"></b-form-select>
          </b-form-group>
        </b-col>

        <b-col v-if="usesFilter('hospital')" cols="12" md="6" lg="4">
          <b-form-group label="โรงพยาบาล" label-for="ex-hospital">
            <b-form-select id="ex-hospital" v-model="hospital" :options="hospitalChoices"></b-form-select>
          </b-form-group>
        </b-col>
      </b-row>

      <div class="d-flex flex-wrap">
        <b-button variant="outline-primary" class="mr-2 mb-2" :disabled="preparing || exporting" @click="buildPreview">
          <b-spinner v-if="preparing" small class="mr-1"></b-spinner>
          <b-icon v-else icon="card-text" class="mr-1"></b-icon>
          สร้างหน้าตัวอย่าง
        </b-button>
        <b-button variant="success" class="mb-2" :disabled="preparing || exporting" @click="download">
          <b-spinner v-if="exporting" small class="mr-1"></b-spinner>
          <b-icon v-else icon="download" class="mr-1"></b-icon>
          Download CSV
        </b-button>
      </div>
    </b-card>

    <!-- ตัวอย่างข้อมูล -->
    <b-overlay :show="preparing" rounded="sm">
      <b-card v-if="preview">
        <div class="text-center mb-3">
          <h5 class="font-weight-bold mb-1">{{ preview.meta.title }}</h5>
          <div v-for="(line, index) in preview.meta.lines" :key="index" class="small text-muted">{{ line }}</div>
        </div>

        <div class="d-flex justify-content-between align-items-center mb-2">
          <small class="text-muted">ไฟล์: <code>{{ preview.filename }}</code></small>
          <b-badge variant="primary" pill>{{ preview.total }} รายการ</b-badge>
        </div>

        <b-table
          :items="preview.rows"
          :fields="previewFields"
          head-variant="dark"
          small
          bordered
          striped
          responsive
          sticky-header="480px"
          show-empty
          empty-text="ไม่พบข้อมูลตามเงื่อนไขที่เลือก"
          class="f_s_90p"
        />
      </b-card>
      <b-card v-else>
        <empty-state
          icon="file-earmark-spreadsheet"
          title="กรุณากดสร้างหน้าตัวอย่าง"
          description="เลือกเงื่อนไขด้านบน แล้วกด “สร้างหน้าตัวอย่าง” เพื่อดูข้อมูลก่อนดาวน์โหลด"
        />
      </b-card>
    </b-overlay>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import exporter from "../../mixins/exporter";
import PageHeader from "../../components/PageHeader.vue";
import EmptyState from "../../components/EmptyState.vue";

export default {
  name: "Export",
  components: { PageHeader, EmptyState },
  mixins: [common, exporter],
  data() {
    return {
      // ค่าเงื่อนไขที่ผู้ใช้เลือก (ข้อมูลชั่วคราวของ UI)
      type: "signsheet",
      contactId: "0",
      year: this.$store.getters.currentYear,
      province: "all",
      hospital: "all",
      preview: null, // ผลลัพธ์ล่าสุดจาก action prepareExport
      preparing: false,
    };
  },
  computed: {
    ...mapGetters(["exportDatasets", "contacts", "yearOptions", "provinces", "hospitals"]),
    datasetOptions() {
      return this.exportDatasets.map((d) => ({ value: d.value, text: d.text }));
    },
    currentDataset() {
      return this.exportDatasets.find((d) => d.value === this.type) || { filters: [] };
    },
    provinceChoices() {
      return [{ value: "all", text: "ทั้งหมด" }].concat(this.provinces.map((p) => ({ value: p, text: p })));
    },
    hospitalChoices() {
      const list = this.hospitals
        .filter((h) => this.province === "all" || h.province === this.province)
        .map((h) => ({ value: h.id, text: h.nameTh }));
      return [{ value: "all", text: "ทั้งหมด" }].concat(list);
    },
    previewFields() {
      return this.preview ? this.preview.columns.map((c) => ({ key: c.key, label: c.label })) : [];
    },
    params() {
      return {
        year: this.year,
        province: this.province,
        hospitalId: this.hospital,
        contactId: this.contactId,
      };
    },
  },
  watch: {
    // เงื่อนไขเปลี่ยน ตัวอย่างเดิมไม่ตรงแล้ว ให้ล้างทิ้ง
    type() {
      this.preview = null;
    },
    params() {
      this.preview = null;
    },
  },
  methods: {
    usesFilter(name) {
      return this.currentDataset.filters.indexOf(name) !== -1;
    },
    onProvinceChange() {
      this.hospital = "all";
    },
    async buildPreview() {
      if (this.preparing) return;
      this.preparing = true;
      try {
        this.preview = await this.$store.dispatch("prepareExport", { type: this.type, ...this.params });
      } catch (error) {
        this.preview = null;
        this.notifyError(error, "สร้างหน้าตัวอย่างไม่สำเร็จ");
      } finally {
        this.preparing = false;
      }
    },
    download() {
      return this.exportDataset(this.type, this.params);
    },
  },
};
</script>
