<template>
  <div class="container py-4 checklist-page">
    <page-header
      icon="card-checklist"
      variant="warning"
      :title="`แบบประเมินความพึงพอใจในการตรวจสุขภาพประจำปี ${yearBE}`"
    >
    </page-header>

    <div class="mb-3">
      <b-badge variant="success" pill class="mr-2 p-2">คุณทำแบบประเมินแล้ว {{ stats.mine }} ครั้ง</b-badge>
      <b-badge variant="warning" pill class="mr-2 p-2">พนักงานทำแบบประเมิน {{ stats.respondents }} คน</b-badge>
      <b-badge variant="danger" pill class="p-2">แบบประเมินทั้งหมด {{ stats.total }} ครั้ง</b-badge>
    </div>

    <b-card no-body>
      <b-tabs v-model="tabIndex" card>
        <b-tab title="แบบประเมินความพึงพอใจ">
          <survey-form />
        </b-tab>

        <b-tab title="ความคืบหน้า Checklist">
          <!-- ภาพรวม -->
          <b-row class="align-items-center mb-3">
            <b-col cols="12" md="5" class="mb-2 mb-md-0">
              <b-form-select v-model="hospitalFilter" :options="hospitalFilterOptions" size="sm"></b-form-select>
            </b-col>
            <b-col cols="12" md="7">
              <div class="d-flex justify-content-between small mb-1">
                <span>
                  เสร็จสิ้น <strong>{{ stats2.completed }}</strong> จาก <strong>{{ stats2.total }}</strong> รายการ
                </span>
                <strong>{{ stats2.percent }}%</strong>
              </div>
              <b-progress :value="stats2.percent" :max="100" height="0.9rem" variant="success" animated></b-progress>
            </b-col>
          </b-row>

          <div class="mb-3">
            <b-badge
              v-for="o in statusSummary"
              :key="o.value"
              :variant="o.variant"
              pill
              class="mr-2 p-2"
            >
              {{ o.text }} {{ o.count }}
            </b-badge>
          </div>

          <b-alert :show="!isAdmin" variant="info" class="py-2">
            <b-icon icon="info-circle-fill" class="mr-1"></b-icon>เฉพาะ Admin ที่เปลี่ยนสถานะรายการได้
          </b-alert>

          <b-table
            :items="items"
            :fields="fields"
            head-variant="dark"
            small
            bordered
            striped
            hover
            responsive
            show-empty
            empty-text="ไม่พบรายการ Checklist"
            class="f_s_90p"
          >
            <template #cell(title)="data">
              <div class="font-weight-bold">{{ data.value }}</div>
              <small class="text-muted">{{ display(data.item.description) }}</small>
            </template>
            <template #cell(status)="data">
              <b-form-select
                :key="`${data.item.id}-${selectNonce}`"
                :value="data.value"
                :options="statusOptions"
                size="sm"
                :disabled="!isAdmin || busyId === data.item.id"
                :aria-label="`สถานะของ ${data.item.title}`"
                @change="changeStatus(data.item, $event)"
              ></b-form-select>
              <b-spinner v-if="busyId === data.item.id" small class="ml-1"></b-spinner>
            </template>
            <template #cell(completedAt)="data">{{ formatDateTime(data.value) }}</template>
            <template #cell(updatedAt)="data">{{ formatDateTime(data.value) }}</template>
            <template #cell(actions)="data">
              <b-button
                size="sm"
                variant="outline-success"
                :disabled="!isAdmin || data.item.status === 'completed' || busyId === data.item.id"
                @click="changeStatus(data.item, 'completed')"
              >
                <b-icon icon="check2"></b-icon> เสร็จสิ้น
              </b-button>
            </template>
          </b-table>
        </b-tab>
      </b-tabs>
    </b-card>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import PageHeader from "../../components/PageHeader.vue";
import SurveyForm from "../../components/SurveyForm.vue";

export default {
  name: "Checklist",
  components: { PageHeader, SurveyForm },
  mixins: [common],
  data() {
    return {
      // ค่าควบคุม UI ชั่วคราว
      tabIndex: this.$route.query.tab === "progress" ? 1 : 0,
      hospitalFilter: null,
      busyId: null,
      selectNonce: 0, // เพิ่มค่าเมื่อบันทึกล้มเหลว เพื่อให้ช่องเลือกสถานะย้อนกลับเป็นค่าใน Store
      fields: [
        { key: "code", label: "รหัส", sortable: true },
        { key: "hospitalName", label: "โรงพยาบาล", sortable: true },
        { key: "title", label: "รายการ", sortable: true },
        { key: "status", label: "สถานะ", sortable: true, thStyle: { minWidth: "170px" } },
        { key: "completedAt", label: "วันที่เสร็จสิ้น" },
        { key: "updatedAt", label: "อัปเดตล่าสุด" },
        { key: "actions", label: "" },
      ],
    };
  },
  computed: {
    ...mapGetters([
      "yearBE",
      "currentYear",
      "isAdmin",
      "statusOptions",
      "checklistRows",
      "checklistStats",
      "hospitalOptions",
      "surveyStats",
    ]),
    stats() {
      return this.surveyStats(this.currentYear);
    },
    stats2() {
      return this.checklistStats(this.hospitalFilter);
    },
    hospitalFilterOptions() {
      return [{ value: null, text: "ทุกโรงพยาบาล" }].concat(this.hospitalOptions);
    },
    items() {
      return this.checklistRows.filter(
        (c) => this.hospitalFilter === null || c.hospitalId === this.hospitalFilter
      );
    },
    statusSummary() {
      return this.statusOptions.map((o) => ({
        ...o,
        count: this.items.filter((c) => c.status === o.value).length,
      }));
    },
  },
  methods: {
    async changeStatus(item, status) {
      if (this.busyId !== null || item.status === status) return;
      this.busyId = item.id;
      try {
        await this.$store.dispatch("changeChecklistStatus", { id: item.id, status });
        const text = this.$store.getters.statusMeta(status).text;
        this.notify("อัปเดตสำเร็จ", `เปลี่ยนสถานะ "${item.title}" เป็น ${text}`, "success");
      } catch (error) {
        this.selectNonce += 1;
        this.notifyError(error, "เปลี่ยนสถานะไม่สำเร็จ");
      } finally {
        this.busyId = null;
      }
    },
  },
};
</script>

<style scoped>
.checklist-page {
  max-width: 980px;
}
</style>
