<template>
  <b-table
    :items="rows"
    :fields="fields"
    head-variant="dark"
    small
    bordered
    striped
    hover
    responsive
    show-empty
    empty-text="ไม่พบข้อมูลที่ต้องการ"
    class="summary-table"
  >
    <template #cell(name)="data">
      <span class="font-weight-bold">{{ data.value }}</span>
    </template>
    <template #cell(pending)="data">
      <span class="text-secondary">{{ data.value }}</span>
    </template>
    <template #cell(inProgress)="data">
      <span class="text-info">{{ data.value }}</span>
    </template>
    <template #cell(completed)="data">
      <span class="text-success font-weight-bold">{{ data.value }}</span>
    </template>
    <template #cell(cancelled)="data">
      <span class="text-danger">{{ data.value }}</span>
    </template>
    <template #cell(percent)="data">
      <b-progress :max="100" height="1.1rem" show-value>
        <b-progress-bar :value="data.value" :variant="progressVariant(data.value)"></b-progress-bar>
      </b-progress>
    </template>
    <template v-if="totals" #custom-foot>
      <b-tr class="font-weight-bold bg-light">
        <b-td :colspan="showProvince ? 2 : 1" class="text-right">รวมทั้งหมด</b-td>
        <b-td class="text-center">{{ totals.total }}</b-td>
        <b-td class="text-center">{{ totals.pending }}</b-td>
        <b-td class="text-center">{{ totals.inProgress }}</b-td>
        <b-td class="text-center">{{ totals.completed }}</b-td>
        <b-td class="text-center">{{ totals.cancelled }}</b-td>
        <b-td>{{ totals.percent }}%</b-td>
      </b-tr>
    </template>
  </b-table>
</template>

<script>
export default {
  name: "SummaryTable",
  props: {
    rows: { type: Array, default: () => [] },
    totals: { type: Object, default: null },
    nameLabel: { type: String, default: "ชื่อ" },
    showProvince: { type: Boolean, default: false },
  },
  computed: {
    fields() {
      const cellClass = "text-center";
      const list = [{ key: "name", label: this.nameLabel, sortable: true }];
      if (this.showProvince) list.push({ key: "province", label: "จังหวัด", sortable: true });
      return list.concat([
        { key: "total", label: "ทั้งหมด", sortable: true, class: cellClass },
        { key: "pending", label: "รอดำเนินการ", sortable: true, class: cellClass },
        { key: "inProgress", label: "กำลังดำเนินการ", sortable: true, class: cellClass },
        { key: "completed", label: "เสร็จสิ้น", sortable: true, class: cellClass },
        { key: "cancelled", label: "ยกเลิก", sortable: true, class: cellClass },
        { key: "percent", label: "ความสำเร็จ", sortable: true, thStyle: { minWidth: "140px" } },
      ]);
    },
  },
  methods: {
    progressVariant(value) {
      if (value >= 80) return "success";
      if (value >= 40) return "info";
      return "warning";
    },
  },
};
</script>
