// src/mixins/common.js
// เมธอดที่ใช้ร่วมกันทุกหน้า: toast, จัดรูปแบบวันที่, นำทาง
import { formatDate, formatDateTime } from "../utils/format";

export default {
  methods: {
    formatDate,
    formatDateTime,
    display(value) {
      return value === null || value === undefined || value === "" ? "-" : value;
    },
    notify(title, message, variant = "info") {
      this.$bvToast.toast(message, {
        title,
        variant,
        solid: true,
        autoHideDelay: 4000,
        toaster: "b-toaster-top-right",
      });
    },
    notifyError(error, title = "เกิดข้อผิดพลาด") {
      const message =
        error && error.message ? error.message : "ไม่สามารถดำเนินการได้ กรุณาลองใหม่อีกครั้ง";
      this.notify(title, message, "danger");
    },
    // vue-router รุ่นใหม่ push() คืนค่า Promise ซึ่งอาจ reject เมื่อ navigate ซ้ำ
    navigate(location) {
      const result = this.$router.push(location);
      if (result && typeof result.catch === "function") result.catch(() => {});
    },
    replaceRoute(location) {
      const result = this.$router.replace(location);
      if (result && typeof result.catch === "function") result.catch(() => {});
    },
  },
};
