import Vue from "vue";
import Router from "vue-router";
import { store } from "../store";

import Home from "../views/home/Home.vue";
import choose_hospital from "../views/program/choose_hospital.vue";
import summary from "../views/summary/summary.vue";
import download from "../views/export/export.vue";
import checklist from "../views/checklist/checklist.vue";
import db_checklist from "../views/db_checklist/db_checklist.vue";

Vue.use(Router);

const router = new Router({
  routes: [
    {
      path: "/",
      name: "Home",
      component: Home,
      meta: { requiresAuth: true, title: "ตรวจสุขภาพ : หน้าแรก" },
    },
    {
      path: "/choose_hospital/:eid?",
      name: "choose_hospital",
      component: choose_hospital,
      meta: { requiresAuth: true, title: "ตรวจสุขภาพ : เลือกโรงพยาบาล" },
    },
    {
      path: "/summary",
      name: "summary",
      component: summary,
      meta: { requiresAuth: true, title: "ตรวจสุขภาพ : ข้อมูลพนักงาน" },
    },
    {
      path: "/export",
      name: "export",
      component: download,
      meta: { requiresAuth: true, requiresAdmin: true, title: "ตรวจสุขภาพ : ดาวน์โหลด" },
    },
    {
      path: "/checklist",
      name: "checklist",
      component: checklist,
      // ต้องเลือกโรงพยาบาลก่อน จึงจะทำ Checklist / แบบประเมินได้
      meta: { requiresAuth: true, requiresHospital: true, title: "ตรวจสุขภาพ : Checklist และประเมินผล" },
    },
    {
      path: "/db_checklist",
      name: "db_checklist",
      component: db_checklist,
      meta: { requiresAuth: true, requiresAdmin: true, title: "ตรวจสุขภาพ : จัดการข้อมูล Checklist" },
    },
    { path: "*", redirect: "/" },
  ],
});

router.beforeEach((to, from, next) => {
  document.title = to.meta.title || "ตรวจสุขภาพประจำปี";

  if (to.meta.requiresAuth && !store.getters.isAuthenticated) {
    return next({ name: "Home" });
  }

  if (to.meta.requiresAdmin && !store.getters.isAdmin) {
    return next({ name: "Home", query: { denied: "1" } });
  }

  // ผู้ใช้ทั่วไปต้องเลือกโรงพยาบาลก่อน (Admin ข้ามได้ เพื่อจัดการข้อมูล)
  if (to.meta.requiresHospital && !store.getters.isAdmin) {
    const me = store.getters.myParticipant;
    if (!me || !me.hospitalId) {
      return next({ name: "choose_hospital", query: { need: "hospital" } });
    }
  }

  next();
});

export default router;
