// src/utils/csv.js
// สร้างและดาวน์โหลดไฟล์ CSV ใน Browser เท่านั้น (ไม่ส่งข้อมูลไป Backend)
const BOM = "﻿"; // UTF-8 BOM เพื่อให้ Excel อ่านภาษาไทยได้ถูกต้อง

// ป้องกัน CSV/Formula injection เมื่อเปิดใน Excel
const needsFormulaGuard = (text) => text.length > 1 && /^[=+\-@\t\r]/.test(text);

export const escapeCsvCell = (value) => {
  if (value === null || value === undefined) return "";
  let text = typeof value === "string" ? value : String(value);
  if (typeof value === "string" && needsFormulaGuard(text)) text = `'${text}`;
  if (/[",\r\n]/.test(text)) text = `"${text.replace(/"/g, '""')}"`;
  return text;
};

export const buildCsv = (columns, rows) => {
  const header = columns.map((c) => escapeCsvCell(c.label)).join(",");
  const lines = rows.map((row) => columns.map((c) => escapeCsvCell(row[c.key])).join(","));
  return BOM + [header].concat(lines).join("\r\n");
};

export const downloadCsv = (filename, columns, rows) => {
  const blob = new Blob([buildCsv(columns, rows)], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.style.display = "none";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};
