<template>
  <div class="container-xl py-4">
    <page-header
      icon="card-list"
      variant="primary"
      title="ข้อมูลพนักงาน"
      subtitle="รายชื่อผู้เข้ารับการตรวจสุขภาพ และสรุปผลตามโรงพยาบาล โปรแกรม และสถานะ"
    >
      <b-form-select
        v-model="year"
        :options="yearOptions"
        size="sm"
        class="year-select"
        aria-label="ประจำปี"
        @change="onYearChange"
      ></b-form-select>
    </page-header>

    <!-- สรุปตามสถานะ -->
    <b-row class="mb-2">
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="ทั้งหมด" :value="counts.total" icon="people-fill" variant="primary" />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="เสร็จสิ้น" :value="counts.completed" icon="check2-circle" variant="success" />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="รอดำเนินการ / กำลังดำเนินการ" :value="counts.waiting" icon="hourglass-split" variant="info" />
      </b-col>
      <b-col cols="12" sm="6" lg="3" class="mb-3">
        <stat-card label="ยกเลิก" :value="counts.cancelled" icon="x-circle" variant="danger" />
      </b-col>
    </b-row>

    <b-card no-body>
      <b-tabs card>
        <!-- รายชื่อพนักงาน -->
        <b-tab title="รายชื่อพนักงาน" active>
          <b-row class="align-items-center mb-3">
            <b-col cols="12" md="5" lg="4" class="mb-2 mb-md-0">
              <b-input-group size="sm">
                <b-input-group-prepend is-text><b-icon icon="search"></b-icon></b-input-group-prepend>
                <b-form-input v-model="filter" type="search" placeholder="ค้นหาคำที่ต้องการ"></b-form-input>
                <b-input-group-append>
                  <b-button :disabled="!filter" @click="filter = ''">ล้าง</b-button>
                </b-input-group-append>
              </b-input-group>
            </b-col>
            <b-col cols="12" md="7" lg="8" class="text-md-right">
              <span class="mr-3 small">
                ผู้มีสิทธิ์ <strong>{{ counts.eligible }}</strong>
                · เลือกแล้ว <strong class="text-success">{{ counts.selected }}</strong>
                · ยังไม่ได้เลือก <strong class="text-danger">{{ counts.notSelected }}</strong>
              </span>
              <b-button
                variant="outline-success"
                size="sm"
                :disabled="exporting || rows.length === 0"
                @click="download"
              >
                <b-spinner v-if="exporting" small class="mr-1"></b-spinner>
                <b-icon v-else icon="download" class="mr-1"></b-icon>
                Download CSV
              </b-button>
            </b-col>
          </b-row>

          <b-overlay :show="busy" rounded="sm" spinner-small>
            <b-table
              :items="rows"
              :fields="fields"
              :filter="filter"
              :current-page="currentPage"
              :per-page="perPage"
              head-variant="dark"
              small
              bordered
              striped
              hover
              responsive
              show-empty
              empty-text="ไม่พบข้อมูลที่ต้องการ"
              empty-filtered-text="ไม่พบข้อมูลที่ตรงกับคำค้นหา"
              class="f_s_90p"
              @filtered="onFiltered"
            >
              <template #cell(no)="data">{{ data.index + 1 + (currentPage - 1) * perPage }}</template>
              <template #cell(yearBE)="data">{{ data.item.year + 543 }}</template>
              <template #cell(programName)="data">
                <div class="d-flex align-items-center">
                  <span class="text-primary font-weight-bold mr-2">{{ display(data.value) }}</span>
                  <b-icon
                    v-if="hasProgramDetail(data.item.programId)"
                    v-b-popover.hover="'คลิกดูรายละเอียด'"
                    icon="info-circle-fill"
                    variant="info"
                    scale="1.2"
                    class="pointer"
                    @click="openProgram(data.item.programId)"
                  ></b-icon>
                </div>
              </template>
              <template #cell(hospitalName)="data">
                <span :class="data.value ? '' : 'text-danger font-weight-bold'">
                  {{ data.value || "ยังไม่เลือกโรงพยาบาล" }}
                </span>
              </template>
              <template #cell(eligibleDate)="data">{{ formatDate(data.value) }}</template>
              <template #cell(status)="data"><status-badge :status="data.value" /></template>
              <template #cell(surveyDone)="data">
                <span :class="data.value ? 'text-success' : 'text-muted'">
                  {{ data.value ? "ประเมินแล้ว" : "ยังไม่ประเมิน" }}
                </span>
              </template>
            </b-table>
          </b-overlay>

          <div v-if="totalRows > perPage" class="d-flex justify-content-between align-items-center">
            <small class="text-muted">แสดง {{ pageFrom }}-{{ pageTo }} จาก {{ totalRows }} รายการ</small>
            <b-pagination v-model="currentPage" :total-rows="totalRows" :per-page="perPage" size="sm" class="mb-0" />
          </div>
        </b-tab>

        <!-- สรุปตามโรงพยาบาล -->
        <b-tab title="สรุปตามโรงพยาบาล">
          <summary-table
            :rows="hospitalSummary"
            :totals="counts"
            name-label="โรงพยาบาล"
            show-province
          />
        </b-tab>

        <!-- สรุปตามโปรแกรม -->
        <b-tab title="สรุปตามโปรแกรม">
          <summary-table :rows="programSummary" :totals="counts" name-label="โปรแกรมตรวจสุขภาพ" />
        </b-tab>
      </b-tabs>
    </b-card>

    <program-info-modal :program="modalProgram" />
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import common from "../../mixins/common";
import exporter from "../../mixins/exporter";
import PageHeader from "../../components/PageHeader.vue";
import StatCard from "../../components/StatCard.vue";
import StatusBadge from "../../components/StatusBadge.vue";
import SummaryTable from "../../components/SummaryTable.vue";
import ProgramInfoModal from "../../components/ProgramInfoModal.vue";

export default {
  name: "Summary",
  components: { PageHeader, StatCard, StatusBadge, SummaryTable, ProgramInfoModal },
  mixins: [common, exporter],
  data() {
    return {
      // ค่าควบคุม UI ชั่วคราว
      year: this.$store.getters.currentYear,
      filter: "",
      busy: false,
      currentPage: 1,
      perPage: 10,
      filteredCount: null,
      modalProgramId: null,
      fields: [
        { key: "no", label: "ลำดับ" },
        { key: "employeeCode", label: "รหัส", sortable: true },
        { key: "fullName", label: "ชื่อ-นามสกุล", sortable: true },
        { key: "sex", label: "เพศ", sortable: true },
        { key: "yearBE", label: "ประจำปี", sortable: true },
        { key: "hospitalProvince", label: "จังหวัด", sortable: true },
        { key: "programName", label: "โปรแกรม", sortable: true },
        { key: "hospitalName", label: "โรงพยาบาล", sortable: true },
        { key: "eligibleDate", label: "วันที่สามารถเริ่มตรวจ", sortable: true },
        { key: "status", label: "สถานะ", sortable: true },
        { key: "surveyDone", label: "ประเมินผล", sortable: true },
      ],
    };
  },
  computed: {
    ...mapGetters([
      "yearOptions",
      "participantsByYear",
      "participantCounts",
      "summaryByHospital",
      "summaryByProgram",
      "programById",
    ]),
    rows() {
      return this.participantsByYear(this.year);
    },
    counts() {
      return this.participantCounts(this.year);
    },
    hospitalSummary() {
      return this.summaryByHospital(this.year);
    },
    programSummary() {
      return this.summaryByProgram(this.year);
    },
    totalRows() {
      return this.filteredCount === null ? this.rows.length : this.filteredCount;
    },
    pageFrom() {
      return this.totalRows === 0 ? 0 : (this.currentPage - 1) * this.perPage + 1;
    },
    pageTo() {
      return Math.min(this.currentPage * this.perPage, this.totalRows);
    },
    modalProgram() {
      return this.modalProgramId ? this.programById(this.modalProgramId) : null;
    },
  },
  watch: {
    filter() {
      this.currentPage = 1;
    },
  },
  beforeDestroy() {
    clearTimeout(this.timer);
  },
  methods: {
    onFiltered(items) {
      this.filteredCount = items.length;
      this.currentPage = 1;
    },
    onYearChange() {
      // จำลองการโหลดข้อมูลเมื่อเปลี่ยนปี
      this.busy = true;
      this.currentPage = 1;
      this.filteredCount = null;
      clearTimeout(this.timer);
      this.timer = setTimeout(() => {
        this.busy = false;
      }, 400);
    },
    hasProgramDetail(programId) {
      const program = programId ? this.programById(programId) : null;
      return !!program && program.items.length > 0;
    },
    openProgram(programId) {
      this.modalProgramId = programId;
      this.$bvModal.show("bv-pro-info");
    },
    download() {
      return this.exportDataset("participants", { year: this.year });
    },
  },
};
</script>

<style scoped>
.year-select {
  min-width: 110px;
}
</style>
