<template>
  <div id="app" class="app-shell">
    <b-navbar toggleable="lg" type="dark" class="app-navbar" sticky>
      <b-navbar-brand :to="{ name: 'Home' }">
        <b-icon icon="person-check-fill" scale="1.25" class="mr-2"></b-icon>
        ตรวจสุขภาพประจำปี {{ yearBE }}
      </b-navbar-brand>

      <b-navbar-toggle target="main-nav"></b-navbar-toggle>

      <b-collapse id="main-nav" is-nav>
        <b-navbar-nav>
          <b-nav-item
            v-for="item in menuItems"
            :key="item.name"
            :to="{ name: item.name }"
            :exact="item.name === 'Home'"
          >
            <b-icon :icon="item.icon" class="mr-1"></b-icon>{{ item.text }}
          </b-nav-item>
        </b-navbar-nav>

        <b-navbar-nav class="ml-auto align-items-lg-center">
          <b-nav-item-dropdown right toggle-class="d-flex align-items-center">
            <template #button-content>
              <b-avatar variant="light" size="2rem" :text="avatarText" class="mr-2"></b-avatar>
              <span class="user-text">
                <span class="d-block font-weight-bold">{{ currentUser.nameTh }}</span>
                <small class="d-block">{{ currentUser.employeeCode }} · {{ roleText }}</small>
              </span>
            </template>
            <b-dropdown-header>ข้อมูลผู้ใช้ (ข้อมูลจำลอง)</b-dropdown-header>
            <b-dropdown-text>{{ currentUser.company }} · {{ currentUser.workPlace }}</b-dropdown-text>
            <b-dropdown-divider></b-dropdown-divider>
            <b-dropdown-header>สลับบทบาทเพื่อทดสอบ</b-dropdown-header>
            <b-dropdown-item :active="isAdmin" @click="setRole('admin')">
              <b-icon icon="shield-lock" class="mr-2"></b-icon>ผู้ดูแลระบบ (Admin)
            </b-dropdown-item>
            <b-dropdown-item :active="!isAdmin" @click="setRole('employee')">
              <b-icon icon="person" class="mr-2"></b-icon>พนักงานทั่วไป
            </b-dropdown-item>
            <b-dropdown-divider></b-dropdown-divider>
            <b-dropdown-item @click="toggleSimulateError">
              <b-icon :icon="settings.simulateError ? 'toggle-on' : 'toggle-off'" class="mr-2"></b-icon>
              จำลอง Error: {{ settings.simulateError ? "เปิด" : "ปิด" }}
            </b-dropdown-item>
            <b-dropdown-item :disabled="resetting" @click="confirmReset">
              <b-icon icon="arrow-counterclockwise" class="mr-2"></b-icon>รีเซ็ตข้อมูลจำลอง
            </b-dropdown-item>
          </b-nav-item-dropdown>
        </b-navbar-nav>
      </b-collapse>
    </b-navbar>

    <b-alert
      :show="settings.simulateError"
      variant="warning"
      class="rounded-0 mb-0 text-center py-2"
    >
      <b-icon icon="exclamation-triangle-fill" class="mr-1"></b-icon>
      เปิดโหมดจำลอง Error อยู่ ทุกการบันทึก/โหลดข้อมูลจะล้มเหลว (ปิดได้จากเมนูผู้ใช้มุมขวาบน)
    </b-alert>

    <main class="app-main">
      <div v-if="!loaded" class="text-center py-5 mt-5">
        <b-spinner variant="primary" label="กำลังโหลดข้อมูล"></b-spinner>
        <p class="mt-3 text-muted">กำลังโหลดข้อมูล...</p>
      </div>
      <router-view v-else />
    </main>

    <footer class="app-footer text-center text-muted py-3">
      <small>Health Check Up Program · ระบบสาธิตด้วยข้อมูลจำลอง ไม่เชื่อมต่อฐานข้อมูลจริง</small>
    </footer>
  </div>
</template>

<script>
import { mapGetters, mapState } from "vuex";
import common from "./mixins/common";

export default {
  name: "App",
  mixins: [common],
  data() {
    return {
      resetting: false,
    };
  },
  computed: {
    ...mapState(["loaded"]),
    ...mapGetters(["yearBE", "currentUser", "isAdmin", "settings", "myParticipant"]),
    menuItems() {
      const items = [
        { name: "Home", text: "หน้าแรก", icon: "house-door" },
        { name: "choose_hospital", text: "เลือกโรงพยาบาล", icon: "building" },
        { name: "summary", text: "ข้อมูลพนักงาน", icon: "card-list" },
        { name: "checklist", text: "แบบประเมิน", icon: "card-checklist" },
      ];
      if (this.isAdmin) {
        items.push(
          { name: "export", text: "Export", icon: "download" },
          { name: "db_checklist", text: "จัดการข้อมูล", icon: "journal-check" }
        );
      }
      return items;
    },
    avatarText() {
      return (this.currentUser.nameTh || "?").charAt(0);
    },
    roleText() {
      return this.isAdmin ? "Admin" : "พนักงาน";
    },
    myHospitalId() {
      return this.myParticipant ? this.myParticipant.hospitalId : null;
    },
  },
  watch: {
    // ตรวจสิทธิ์หน้าปัจจุบันซ้ำ เมื่อสลับบทบาท หรือข้อมูลถูกรีเซ็ต
    isAdmin() {
      this.recheckRoute();
    },
    myHospitalId() {
      this.recheckRoute();
    },
  },
  created() {
    this.$store.dispatch("initApp");
  },
  methods: {
    setRole(role) {
      this.$store.commit("SET_ROLE", role);
    },
    toggleSimulateError() {
      this.$store.commit("SET_SIMULATE_ERROR", !this.settings.simulateError);
    },
    recheckRoute() {
      const meta = this.$route.meta || {};
      if (meta.requiresAdmin && !this.isAdmin) {
        this.replaceRoute({ name: "Home" });
      } else if (meta.requiresHospital && !this.isAdmin && !this.myHospitalId) {
        this.replaceRoute({ name: "choose_hospital", query: { need: "hospital" } });
      }
    },
    async confirmReset() {
      const ok = await this.$bvModal.msgBoxConfirm(
        "ข้อมูลที่แก้ไขทั้งหมดจะกลับเป็นข้อมูลจำลองเริ่มต้น ต้องการดำเนินการต่อหรือไม่?",
        {
          title: "รีเซ็ตข้อมูลจำลอง",
          okVariant: "danger",
          okTitle: "รีเซ็ต",
          cancelTitle: "ยกเลิก",
          centered: true,
        }
      );
      if (!ok) return;
      this.resetting = true;
      try {
        await this.$store.dispatch("resetData");
        this.notify("สำเร็จ", "รีเซ็ตข้อมูลกลับเป็นค่าเริ่มต้นแล้ว", "success");
      } catch (error) {
        this.notifyError(error);
      } finally {
        this.resetting = false;
      }
    },
  },
};
</script>

