<template>
  <b-overlay :show="locked" rounded="lg" opacity="0.96" variant="light" class="h-100">
    <template #overlay>
      <div class="text-center px-3">
        <b-icon icon="lock-fill" font-scale="1.6"></b-icon>
        <p class="font-weight-bold mt-2 mb-0">{{ lockedText }}</p>
      </div>
    </template>
    <b-card
      no-body
      class="menu-card h-100"
      role="link"
      tabindex="0"
      @click="open"
      @keyup.enter="open"
    >
      <b-card-body class="d-flex align-items-center">
        <div class="menu-card__icon mr-3" :class="`menu-card__icon--${variant}`">
          <b-icon :icon="icon" font-scale="1.8"></b-icon>
        </div>
        <div>
          <div class="menu-card__title">{{ title }}</div>
          <small v-if="description" class="text-muted">{{ description }}</small>
        </div>
        <b-icon icon="chevron-right" class="ml-auto text-muted"></b-icon>
      </b-card-body>
    </b-card>
  </b-overlay>
</template>

<script>
import common from "../mixins/common";

export default {
  name: "MenuCard",
  mixins: [common],
  props: {
    title: { type: String, required: true },
    description: { type: String, default: "" },
    icon: { type: String, default: "grid" },
    variant: { type: String, default: "primary" },
    to: { type: Object, required: true },
    locked: { type: Boolean, default: false },
    lockedText: { type: String, default: "ไม่สามารถใช้งานได้" },
  },
  methods: {
    open() {
      if (this.locked) return;
      this.navigate(this.to);
    },
  },
};
</script>

